function dayLogs(memberId=null,day=ui.day){return data.logs.filter(l=>l.day===day&&(!memberId||l.memberId===memberId));}
function memberStats(m){const all=data.logs.filter(l=>l.memberId===m.id&&l.day<=ui.day);const current=all.filter(l=>l.day===ui.day);const used=current.filter(l=>l.type!=='carry'&&!l.usesCarry).length;const kills=current.filter(l=>l.type==='kill').length,carries=current.filter(l=>l.type==='carry'||l.usesCarry).length;const contribution=all.reduce((s,l)=>s+l.actual*(data.rates[Math.min(2,Math.max(0,l.stage-2))][l.boss-1]||1),0);return {member:m,logs:all,damage:all.reduce((s,l)=>s+l.actual,0),dayDamage:current.reduce((s,l)=>s+l.actual,0),used,remaining:Math.max(0,data.settings.daily-used),carry:Math.max(0,kills-carries),shots:all.length,contribution,average:all.length?contribution/all.length:0};}
function allStats(){return data.members.filter(m=>m.status==='active').map(memberStats);}
function currentBattleDay(){return Math.min(data.rules?.days||data.settings.days,Math.max(1,...data.logs.map(e=>Number(e.day)||1),...(data.dayClosures||[]).map(e=>Number(e.day)+1)));}
