function defaultRules(){return {days:5,daily:3,startStage:2,levels:[{stage:1,count:0},{stage:2,count:3},{stage:3,count:6},{stage:4,count:9999}],autoContribution:true,factor:.95,samples:10,baseline:30000000,stage3Mode:'auto',carryVisible:true,startDate:'2026-10-22'};}
function seasonLevels(rules){let next=1;return rules.levels.map(l=>{const count=Number(l.count)||0;const entry={stage:Number(l.stage),count,start:next,end:count?next+count-1:next-1};next+=count;return entry;});}
function stageFor(lap,rules){return seasonLevels(rules).find(l=>l.count&&lap>=l.start&&lap<=l.end)?.stage||seasonLevels(rules).filter(l=>l.count>0).at(-1)?.stage||rules.startStage;}
function makeBossSettings(){return Array.from({length:5},(_,i)=>({id:i+1,name:GAME_ASSETS.bosses[i+1].name,portraitKey:String(i+1),icon:['leaf','diamond','flame','shield','moon'][i],hp:{1:12000000,2:30000000+i*2000000,3:55000000+i*3000000,4:1350000000+i*40000000,5:1700000000+i*50000000,6:2000000000+i*60000000},game:{1:1.2,2:2,3:2.8,4:4.5,5:5,6:6},contribution:{1:.1,2:.5,3:.3,4:.1,5:.1,6:.1}}));}
function sampleTactics(){const base=seed().tactics;const result=base.map((t,i)=>({...t,title:t.party.join(' '),note:'',video:'',links:[],duration:90,stage:4,category:i%3===2?'tabi':'main',rows:null}));for(let i=1;i<=5;i++){const t=structuredClone(base[(i-1)*3]);t.id='early-'+i;t.boss=i;t.stage=3;t.damage=.5;t.hidden=false;t.title=t.party.join(' ');t.note='';t.video='';t.duration=90;t.category='main';result.push(t);const carry=structuredClone(t);carry.id='carry-'+i;carry.stage=4;carry.category='carry';carry.duration=60;carry.damage=1.8;carry.text='1:00 AUTO ON\n0:43 '+carry.party[4]+' SET\n0:20 '+carry.party[1]+' 한번만\n0:05 전원 SET';result.push(carry);}return result;}
function fixtureSeason(key,memberIds,currentDay=3){const rules=defaultRules();rules.startDate=key+'-22';const settings=makeBossSettings(),states=settings.map(b=>({id:b.id,lap:1,hp:b.hp[2]})),logs=[];let seq=0;const sampleOffset=Number(key.slice(-2))*7;
 const choose=(n)=>{const min=Math.min(...states.map(b=>b.lap+(b.hp===0?1:0)));const slowStage=stageFor(min,rules);const allowed=states.filter(b=>{const next=b.lap+(b.hp===0?1:0);return next<=min+1&&stageFor(next,rules)<=slowStage;});return allowed[n%allowed.length];};
 const attack=(memberId,day,b,damage,carry=false)=>{if(!b.hp){b.lap++;b.hp=settings[b.id-1].hp[stageFor(b.lap,rules)];}const actual=Math.min(b.hp,damage);b.hp-=actual;logs.push({id:uid(),seq:++seq,memberId,day,boss:b.id,damage,actual,carry,usesCarry:carry,type:!b.hp?'kill':carry?'carry':'normal',note:'',bonus:0,gameAt:key+'-'+String(21+day).padStart(2,'0')+'T'+String(18+Math.floor(seq/120)).padStart(2,'0')+':'+String(seq%60).padStart(2,'0'),created:seq});return b.hp===0;};
 for(let day=1;day<=currentDay;day++)memberIds.forEach((id,i)=>{const count=day<currentDay||currentDay===5?3:i<14?3:i<22?2:i<27?1:0;for(let n=0;n<count;n++){let b=choose(i+n+day+sampleOffset);const nextStage=stageFor(b.lap+(b.hp===0?1:0),rules),hp=b.hp||settings[b.id-1].hp[nextStage];let damage=nextStage<4?hp:(245+(i*31+n*27+day*11+sampleOffset)%130)*1000000;if((i+n)%17===0)damage=hp+10000000;const killed=attack(id,day,b,damage);if(killed&&(day<currentDay||i%4!==0)){b=choose(i+n+day+sampleOffset+1);const stage=stageFor(b.lap+(b.hp===0?1:0),rules);attack(id,day,b,stage<4?(b.hp||settings[b.id-1].hp[stage]):185000000,true);}}});
 return {logs,tactics:sampleTactics(),recommendations:[],rules,bossSettings:settings,dayClosures:[],memberships:Object.fromEntries(memberIds.map(id=>[id,{from:1,to:5}])),notices:{3:'',4:''},result:{rank:null,sealed:false,confirmedAt:null,winners:null}};
}
function snapshotSeason(){if(!data.seasons||!ui.month)return;data.seasons[ui.month]=Object.fromEntries(SEASON_KEYS.map(k=>[k,structuredClone(data[k])]));}
function activateSeason(key){if(!data.seasons[key])return false;snapshotSeason();for(const k of SEASON_KEYS)data[k]=structuredClone(data.seasons[key][k]);ui.month=key;data.activeMonth=key;data.settings.days=data.rules.days;data.settings.daily=data.rules.daily;ui.day=Math.min(data.rules.days,key==='2026-10'?3:data.rules.days);ui.page=1;ui.boss=0;ui.query='';ext.allDays=false;ui.selectedTactic=data.tactics.find(t=>!t.deletedAt&&!t.hidden)?.id;recalculateSeason();persist();return true;}
function engineMonth(){return {events:data.logs,bosses:data.bossSettings,levels:seasonLevels(data.rules),options:{days:data.rules.days,dailyAttacks:data.rules.daily,startStage:data.rules.startStage,autoContribution:data.rules.autoContribution,contributionFactor:data.rules.factor,contributionSamples:data.rules.samples,contributionBaseline:data.rules.baseline}};}
function recalculateSeason(){const month=engineMonth();for(const e of data.logs){e.carry=e.usesCarry!==undefined?!!e.usesCarry:e.type==='carry';e.usesCarry=e.carry;e.bonus=Number(e.bonus)||0;}data.replayWarnings=engineReplay(month);for(const e of data.logs){e.type=e.kill?'kill':e.carry?'carry':'normal';e.game=e.actual*Number(data.bossSettings.find(b=>b.id===e.boss)?.game[e.stage]||1);e.contribution=engineContribution(e,month);}data.bosses=engineProgress(month);data.rates=[2,3,4].map(stage=>data.bossSettings.map(b=>b.contribution[stage]??0));data.settings.days=data.rules.days;data.settings.daily=data.rules.daily;return month;}
function memberSeasonActive(m,day=ui.day){const p=data.memberships[m.id];return p&&day>=p.from&&day<=p.to;}
function statsFor(m,day=ui.day){const logs=data.logs.filter(e=>e.memberId===m.id&&e.day<=day),daily=logs.filter(e=>e.day===day),basics=daily.filter(e=>!e.carry),sources=new Set(daily.filter(e=>e.carry).map(e=>e.carryFrom));const active=memberSeasonActive(m,day);const allowedDays=Array.from({length:day},(_,i)=>i+1).filter(d=>memberSeasonActive(m,d)).length;const contribution=logs.reduce((s,e)=>s+(Number.isFinite(e.contribution)?e.contribution:0),0);return {member:m,logs,damage:logs.reduce((s,e)=>s+e.actual,0),dayDamage:daily.reduce((s,e)=>s+e.actual,0),game:logs.reduce((s,e)=>s+e.game,0),contribution,dayContribution:daily.reduce((s,e)=>s+(e.contribution||0),0),average:logs.length?contribution/logs.length:0,used:basics.length,remaining:active?Math.max(0,data.rules.daily-basics.length):0,carry:basics.filter(e=>e.kill&&!sources.has(e.id)).length,shots:logs.length,basicShots:logs.filter(e=>!e.carry).length,missing:Math.max(0,allowedDays*data.rules.daily-logs.filter(e=>!e.carry).length),active,slots:basics.map(e=>({basic:e,carry:daily.find(c=>c.carryFrom===e.id),pending:e.kill&&!sources.has(e.id)}))};}
function allSeasonStats(day=ui.day){const ids=new Set([...Object.keys(data.memberships),...data.logs.map(e=>e.memberId)]);return data.members.filter(m=>ids.has(m.id)).map(m=>statsFor(m,day));}
function points(v){return Number.isFinite(v)?contributionText(v):'—';}
function seasonSummary(key){const season=key===ui.month?Object.fromEntries(SEASON_KEYS.map(k=>[k,data[k]])):data.seasons[key];if(!season)return null;const stats=data.members.map(m=>{const logs=season.logs.filter(e=>e.memberId===m.id);return {id:m.id,name:m.name,damage:logs.reduce((s,e)=>s+e.actual,0),contribution:logs.reduce((s,e)=>s+(e.contribution||0),0),game:logs.reduce((s,e)=>s+(e.game||0),0)};}).filter(m=>m.damage);const winners={};for(const metric of ['damage','contribution','game'])winners[metric]=[...stats].sort((a,b)=>b[metric]-a[metric]).slice(0,2).map(x=>({id:x.id,name:x.name,value:x[metric]}));return {stats,winners,total:stats.reduce((s,m)=>s+m.damage,0),count:stats.length,attacks:season.logs.length,rank:season.result.rank,sealed:season.result.sealed};}
function initializeSeasons(){if(data.schema!==2){const display={...data.settings};data=seed();data.members=data.members.map((m,i)=>({...m,name:'클랜원 '+String(i+1).padStart(2,'0'),note:'',periods:[{from:'2026-06',to:null}]}));data.members.push({id:'alumni-1',name:'이전 클랜원',uid:'DEMO-9001',status:'graduated',joined:'2026-03-01',left:'2026-08-31',periods:[{from:'2026-03',to:'2026-08'}],note:''});data.schema=2;data.settings={...data.settings,theme:display.theme||'light',large:!!display.large,compact:!!display.compact};data.characters=CHARACTERS.map((name,i)=>({id:'c'+i,name,aliases:[],booster:i%7===0,images:{}}));data.communityLinks=[];data.pinHash=null;data.seasons={};data.activeMonth='2026-10';for(const key of ['2026-08','2026-09','2026-10'])data.seasons[key]=fixtureSeason(key,data.members.filter(m=>m.status==='active').map(m=>m.id),key==='2026-10'?3:5);ui.month='2026-10';for(const k of SEASON_KEYS)data[k]=structuredClone(data.seasons[ui.month][k]);for(const key of ['2026-08','2026-09']){const active=Object.fromEntries(SEASON_KEYS.map(k=>[k,data[k]]));for(const k of SEASON_KEYS)data[k]=structuredClone(data.seasons[key][k]);recalculateSeason();data.result.rank=key==='2026-08'?136:128;data.result.sealed=true;data.seasons[key]=Object.fromEntries(SEASON_KEYS.map(k=>[k,structuredClone(data[k])]));for(const k of SEASON_KEYS)data[k]=active[k];}}else{ui.month=data.activeMonth||'2026-10';for(const k of SEASON_KEYS)if(data.seasons[ui.month]?.[k])data[k]=structuredClone(data.seasons[ui.month][k]);}recalculateSeason();ui.day=Math.min(data.settings.defaultDay||3,data.rules.days);ui.selectedTactic=data.tactics.find(t=>!t.deletedAt&&!t.hidden)?.id;ui.profile='__clan__';}
