function fullBattle(){const logs=getFilteredCompleteLogs(),size=Number(ext.pageSize||20),pages=Math.max(1,Math.ceil(logs.length/size));ui.page=Math.min(ui.page,pages);const closed=data.dayClosures.find(d=>d.day===ui.day);return titleBar('배틀로그',simpleButton('이미지 등록','v2-import-images')+simpleButton('공격 기록','add-log','','primary'))+bossStrip(true)+(data.settings.editable&&!closed?quickLogForm():'')+`<div class="toolbar"><div class="toolbar-left">${bossFilter()}<label class="inline-check"><input type="checkbox" data-input="v2-all-days" ${ext.allDays?'checked':''}>전체 일차</label></div><div class="toolbar-right"><input class="search-input" id="complete-log-search" data-input="v2-log-query" value="${X(ui.query)}" placeholder="이름 · 초성 · 순번" aria-label="공격 기록 검색"><select class="select-field" data-input="log-type" aria-label="공격 유형"><option value="all">전체 유형</option>${['normal','kill','carry'].map(v=>`<option value="${v}" ${ui.logType===v?'selected':''}>${logTypeLabel(v)}</option>`).join('')}</select></div></div><div class="table-tools"><span>${ext.allDays?'전체':ui.day+'일차'} · ${logs.length}건${closed?' · 마감':''}</span><div><label class="inline-check"><input type="checkbox" data-input="v2-sequence" ${ext.sequence?'checked':''}>순번</label><label class="inline-check"><input type="checkbox" data-input="v2-details" ${ext.details?'checked':''}>상세</label>${simpleButton('등록순 '+(ext.logOrder==='asc'?'↑':'↓'),'v2-log-order')}${simpleButton('실행 취소','v2-undo')}${simpleButton('CSV','export-csv')}${data.settings.editable?simpleButton(closed?'마감 취소':'일차 마감',closed?'v2-reopen-day':'v2-close-day'):''}</div></div>${completeLogTable(logs.slice((ui.page-1)*size,ui.page*size))}<div class="pagination"><span>${logs.length?`${(ui.page-1)*size+1}–${Math.min(ui.page*size,logs.length)}`:'0'} / ${logs.length}건</span><div><button data-action="log-page" data-value="${ui.page-1}" ${ui.page<=1?'disabled':''}>이전</button><span>${ui.page}/${pages}</span><button data-action="log-page" data-value="${ui.page+1}" ${ui.page>=pages?'disabled':''}>다음</button></div></div>${data.dayClosures.length?`<details class="fold"><summary>마감 이력</summary>${rowTable(['일차','등록 수','마감 시각'],data.dayClosures.map(c=>`<tr><td>${c.day}일차</td><td>${c.count}건</td><td>${X(c.at)}</td></tr>`))}</details>`:''}`;}
function completeLogTable(logs,mini=false){const headers=[...(!mini&&ext.sequence?['순번']:[]),...(!mini?['일차 · 회차']:[]),'보스','클랜원','기록 피해량',...(!mini&&ext.details?['이전 HP','실제 피해량','남은 HP','가산점','기여도','인게임']:[]),'유형',...(!mini&&(!syncState.started||data.settings.editable)?['관리']:[])];return rowTable(headers,logs.map(e=>`<tr>${!mini&&ext.sequence?`<td class="hide-on-narrow">${e.seq}</td>`:''}${!mini?`<td class="progress-cell"><span>${e.day}일차</span><small>${e.stage}단계 ${e.lap}회차</small></td>`:''}<td><span class="boss-tag" style="${bossStyle(e.boss)}">${e.boss}넴</span></td><td>${memberLink(currentMember(e.memberId))}</td><td class="right numeric">${syncState.started&&!data.settings.editable?`<span>${nf(e.damage)}</span>`:`<button class="damage-edit" data-action="edit-log" data-id="${e.id}">${nf(e.damage)}</button>`}${mini?`<small>${e.day}일차 · ${e.stage}단계 ${e.lap}회차</small>`:''}</td>${!mini&&ext.details?`<td class="right numeric extra-cell" data-label="이전 HP">${nf(e.before)}</td><td class="right numeric extra-cell" data-label="실제 피해량">${nf(e.actual)}</td><td class="right numeric extra-cell" data-label="남은 HP">${nf(e.after)}</td><td class="right numeric extra-cell" data-label="가산점">${syncState.started&&!data.settings.editable?nf(Math.round((e.bonus||0)*10000)):`<button class="damage-edit" data-action="edit-log" data-id="${e.id}">${nf(Math.round((e.bonus||0)*10000))}</button>`}</td><td class="right numeric extra-cell" data-label="기여도">${points(e.contribution)}</td><td class="right numeric extra-cell" data-label="인게임">${nf(e.game)}</td>`:''}<td><span class="type-tag ${e.kill?'kill':e.carry?'carry':''}">${e.role==='초월'?'초월':e.kill?(e.carry?'관통':'격파'):e.carry?'이월타':'일반'}</span></td>${!mini&&(!syncState.started||data.settings.editable)?`<td class="log-manage">${simpleButton('수정','edit-log',e.id,'quiet')}${simpleButton('삭제','entry-delete-log',e.id,'danger quiet')}${ext.details?simpleButton('↑','v2-log-up',e.id,'quiet')+simpleButton('↓','v2-log-down',e.id,'quiet'):''}</td>`:''}</tr>`),`battle-table ${!mini&&ext.details?'expanded':''} ${mini?'small-log':''}`);}
function fullRecords(){return titleBar('기록·통계',ui.tabs.records==='profile'?'':simpleButton('인쇄','print'))+pageTabs([['ranking','월간 순위'],['profile','개인 이력'],['archive','과거 기록'],['history','과거 이력'],['hall','명예의 전당']])+({ranking:completeRanking,profile:completeProfile,archive:completeArchive,history:completeHistory,hall:completeHall}[ui.tabs.records]||completeRanking)();}
function archiveLogPanel(){const logs=getFilteredCompleteLogs(),size=25,pages=Math.max(1,Math.ceil(logs.length/size));ui.page=Math.min(ui.page,pages);return `<div class="toolbar"><div class="toolbar-left">${bossFilter()}<label class="inline-check"><input type="checkbox" data-input="v2-all-days" ${ext.allDays?'checked':''}>전체 일차</label>${dayButtons()}</div><div class="toolbar-right"><input class="search-input" id="complete-log-search" data-input="v2-log-query" aria-label="공격 기록 검색" placeholder="이름 · 초성 · 순번" value="${X(ui.query)}">${simpleButton('CSV','export-csv')}</div></div>`+completeLogTable(logs.slice((ui.page-1)*size,ui.page*size))+`<div class="pagination"><span>${logs.length}건</span><div><button data-action="log-page" data-value="${ui.page-1}" ${ui.page<=1?'disabled':''}>이전</button><span>${ui.page}/${pages}</span><button data-action="log-page" data-value="${ui.page+1}" ${ui.page>=pages?'disabled':''}>다음</button></div></div>`;}
function completeRanking(){
 const metrics=[['damage','피해량'],['contribution','기여도'],['game','인게임 스코어'],['dayDamage','일일 피해량'],['dayContribution','일일 기여도']],metric=metrics.find(([key])=>key===ui.rankSort)||metrics[0],rows=allSeasonStats().sort((a,b)=>(b[metric[0]]||0)-(a[metric[0]]||0)),page=pagedList(rows,'ranking');
 return `<div class="toolbar"><div class="toolbar-left"><select class="select-field" aria-label="순위 지표" data-input="v3-rank-metric">${metrics.map(([key,name])=>`<option value="${key}" ${metric[0]===key?'selected':''}>${name}</option>`).join('')}</select><span class="muted">${ui.day}일차까지</span></div>${simpleButton('CSV','v2-ranking-csv')}</div>`+rowTable(['순위','클랜원',metric[1]+(metric[0].toLowerCase().includes('contribution')?' · 만':'')],page.rows.map((s,i)=>`<tr><td class="center rank-cell">${page.start+i+1}</td><td>${memberLink(s.member)}</td><td class="right numeric" title="${nf(s[metric[0]])}"><strong>${metric[0].toLowerCase().includes('contribution')?points(s[metric[0]]):chartValue(s[metric[0]])}</strong></td></tr>`),'ranking-detail dense-table')+page.footer+`<details class="fold"><summary>순위 그래프</summary>${rankingChart(rows)}</details>`;
}

function profileEvents(){return data.logs.filter(e=>(ui.profile==='__clan__'||e.memberId===ui.profile)&&(!ext.profileStage||e.stage===ext.profileStage)&&(!Number(ext.profileDay)||e.day===Number(ext.profileDay)));}
function bossStatistics(events){return rowTable(['보스','공격 수','피해량 합계','평균 피해량','최고 피해량'],data.bossSettings.map(b=>{const rows=events.filter(e=>e.boss===b.id),total=rows.reduce((s,e)=>s+e.actual,0);return `<tr><td><span class="boss-stat-name">${bossFace(b,'tiny')}<span class="boss-tag" style="${bossStyle(b.id)}">${b.id}넴</span></span></td><td class="right">${rows.length}</td><td class="right numeric">${nf(total)}</td><td class="right numeric">${nf(rows.length?total/rows.length:0)}</td><td class="right numeric">${nf(Math.max(0,...rows.map(e=>e.actual)))}</td></tr>`;}),'boss-statistics');}
function completeProfile(){
 const all=ui.profile==='__clan__',m=all?null:currentMember(ui.profile),events=profileEvents(),damage=events.reduce((s,e)=>s+e.actual,0),contrib=events.reduce((s,e)=>s+(e.contribution||0),0),game=events.reduce((s,e)=>s+e.game,0),stages=[2,3,4].filter(stage=>data.logs.some(e=>e.stage===stage));
 return `<div class="toolbar profile-toolbar"><select id="full-profile-member" class="select-field" aria-label="기록 대상" data-input="v2-profile-member"><option value="__clan__" ${all?'selected':''}>클랜 전체</option>${data.members.map(p=>`<option value="${p.id}" ${p.id===ui.profile?'selected':''}>${X(p.name)}</option>`).join('')}</select><select class="select-field" aria-label="이력 단계" data-input="v2-profile-stage"><option value="0" ${!ext.profileStage?'selected':''}>전체 단계</option>${stages.map(s=>`<option value="${s}" ${ext.profileStage===s?'selected':''}>${s}단계</option>`).join('')}</select>${simpleButton('인쇄','print','','quiet')}</div><dl class="profile-totals"><div><dt>피해량</dt><dd title="${nf(damage)}">${chartValue(damage)}</dd></div><div><dt>기여도 · 만</dt><dd>${points(contrib)}</dd></div><div><dt>인게임</dt><dd title="${nf(game)}">${chartValue(game)}</dd></div></dl>${profileDayDonut(events)}<details class="fold"><summary>일차별 수치</summary>${dailyRecordTable(all,m)}</details><details class="fold"><summary>보스별 통계</summary>${bossStatistics(events)}</details><details class="fold"><summary>단계별 통계</summary>${stages.map(s=>`<h3 class="detail-stage-heading">${s}단계</h3>${bossStatistics(events.filter(e=>e.stage===s))}`).join('')}</details><details class="fold"><summary>공격 상세 · ${events.length}건</summary>${rowTable(['일차','보스','단계·회차','실제 피해량','기여도 · 만','이월'],events.map(e=>`<tr><td>${e.day}일차</td><td>${e.boss}넴</td><td>${e.stage}단계 ${e.lap}회차</td><td class="right numeric">${nf(e.actual)}</td><td class="right numeric">${points(e.contribution)}</td><td class="center">${e.carry?'사용':'—'}</td></tr>`),'profile-attacks')}</details>`;
}

function shareDonut(events){const total=events.reduce((s,e)=>s+e.actual,0)||1;let acc=0;const shares=data.bossSettings.map(b=>{const amount=events.filter(e=>e.boss===b.id).reduce((s,e)=>s+e.actual,0),start=acc;acc+=amount/total*100;return {b,amount,percent:amount/total*100,start,end:acc};});const gradient=shares.map(s=>`var(--b${s.b.id}) ${s.start}% ${s.end}%`).join(',');return `<div class="share-chart"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="${shares.map(s=>s.b.id+'넴 '+s.percent.toFixed(1)+'%').join(', ')}"><span>피해량<br><strong>${eok(total)}억</strong></span></div><div class="share-legend">${shares.map(s=>`<div><span class="boss-tag" style="${bossStyle(s.b.id)}">${s.b.id}넴</span><strong class="numeric">${s.percent.toFixed(1)}%</strong></div>`).join('')}</div></div>`;}
function dailyRecordTable(all,m){const rows=Array.from({length:data.rules.days},(_,i)=>{const day=i+1,events=data.logs.filter(e=>e.day===day&&(all||e.memberId===m.id)&&(!ext.profileStage||e.stage===ext.profileStage)),amount=events.reduce((s,e)=>s+e.actual,0),contrib=events.reduce((s,e)=>s+(e.contribution||0),0),average=allSeasonStats(day).filter(s=>s.active).length||1,clan=data.logs.filter(e=>e.day===day).reduce((s,e)=>s+(e.contribution||0),0)/average;return {day,amount,contrib,average:all?null:clan};}),max=Math.max(1,...rows.map(r=>r.contrib));return rowTable(['일차','피해량','기여도 · 만',...(!all?['클랜 평균 · 만']:[])],rows.map(r=>`<tr><td>${r.day}일차</td><td class="right numeric">${r.amount?short(r.amount):'—'}</td><td class="right numeric"><span>${r.contrib?points(r.contrib):'—'}</span></td>${!all?`<td class="right numeric">${r.day<=ui.day?points(r.average):'—'}</td>`:''}</tr>`),'daily-records');}
function completeArchive(){const currentIsPast=ui.month!==Object.keys(data.seasons).sort().at(-1);const chooser=`<div class="archive-selector"><label for="archive-month">과거 월</label><select id="archive-month" data-input="v2-archive-month" class="select-field">${Object.keys(data.seasons).sort().reverse().map(key=>`<option value="${key}" ${key===ui.month?'selected':''}>${key.replace('-','년 ')}월</option>`).join('')}</select><div class="subview-tabs">${[['summary','요약'],['logs','배틀로그'],['ranking','순위'],['profile','개인 이력'],['tactics','택틱']].map(([k,n])=>`<button data-action="v2-archive-view" data-value="${k}" class="${ext.archiveView===k?'active':''}">${n}</button>`).join('')}</div></div>`;if(ext.archiveView==='logs')return chooser+archiveLogPanel();if(ext.archiveView==='ranking')return chooser+completeRanking();if(ext.archiveView==='profile')return chooser+completeProfile();if(ext.archiveView==='tactics')return chooser+recommendationRows();const sum=seasonSummary(ui.month);return chooser+`<dl class="totals-line"><div><dt>클랜 순위</dt><dd>${sum.rank?sum.rank+'위':'미입력'}</dd></div><div><dt>총 피해량</dt><dd>${eok(sum.total)}억</dd></div><div><dt>참가 인원</dt><dd>${sum.count}명</dd></div><div><dt>공격 기록</dt><dd>${sum.attacks}건</dd></div></dl>`+boardSection('월별 기록',rowTable(['월','참가','피해량','클랜 순위','결과','열기'],Object.keys(data.seasons).sort().reverse().map(key=>{const summary=seasonSummary(key);return `<tr><td>${key.replace('-','.')}</td><td>${summary.count}명</td><td class="right numeric">${eok(summary.total)}억</td><td>${summary.rank?summary.rank+'위':'미입력'}</td><td>${summary.sealed?'확정':'진행 중'}</td><td>${simpleButton('상세','archive-detail',key,'quiet')}</td></tr>`;})))+boardSection('단계별 보스 통계',[2,3,4].map(s=>`<details class="fold" ${s===4?'open':''}><summary>${s}단계</summary>${bossStatistics(data.logs.filter(e=>e.stage===s))}</details>`).join(''));}
function winnersFrom(logs){const stats=data.members.map(m=>{const rows=logs.filter(e=>e.memberId===m.id);return {id:m.id,name:m.name,damage:rows.reduce((s,e)=>s+e.actual,0),contribution:rows.reduce((s,e)=>s+(e.contribution||0),0),game:rows.reduce((s,e)=>s+(e.game||0),0)};}).filter(m=>m.damage);return Object.fromEntries(['damage','contribution','game'].map(metric=>[metric,[...stats].sort((a,b)=>b[metric]-a[metric]).slice(0,2).map(s=>({id:s.id,name:s.name,value:s[metric]}))]));}
function resultFingerprint(logs){return logs.map(e=>`${e.id}:${e.damage}:${e.boss}:${e.memberId}:${e.bonus}`).join('|');}
function winnerText(winners,metric){return (winners?.[metric]||[]).map((p,i)=>`<span class="winner-person"><b>${i+1}위</b> ${X(p.name)}</span>`).join('<span class="winner-separator" aria-hidden="true">/</span>')||'—';}
function completeHistory(){return rowTable(['월','클랜 순위','참가','피해량 1·2위','기여도 1·2위','인게임 1·2위','확정'],Object.keys(data.seasons).sort().reverse().map(key=>{const season=key===ui.month?data:data.seasons[key],summary=seasonSummary(key),changed=season.result.sealed&&season.result.fingerprint!==resultFingerprint(season.logs);return `<tr><td>${key.replace('-','.')}</td><td><button class="text-button" data-action="v2-history-rank" data-id="${key}">${summary.rank?summary.rank+'위':'입력'}</button></td><td>${summary.count}명</td>${['damage','contribution','game'].map(metric=>`<td class="winner-cell">${winnerText(season.result.winners||summary.winners,metric)}</td>`).join('')}<td>${simpleButton(changed?'재확인':summary.sealed?'확정됨':'결과 확정','v2-confirm-season',key,'quiet')}</td></tr>`;}),'history-table');}
function completeHall(){const map=new Map();for(const [key,season]of Object.entries(data.seasons)){const result=key===ui.month?data.result:season.result;if(!result.sealed||!result.winners)continue;for(const metric of ['damage','contribution','game'])result.winners[metric].forEach((person,index)=>{if(!map.has(person.id))map.set(person.id,{id:person.id,name:person.name,damage:[0,0],contribution:[0,0],game:[0,0],total:0,months:[]});const p=map.get(person.id);p[metric][index]++;p.total++;p.months.push({month:key,metric,place:index+1});});}const rows=[...map.values()].sort((a,b)=>b.total-a.total);return `<div class="table-tools"><span>확정한 월별 결과 기준</span></div>`+rowTable(['클랜원','피해량 1위 / 2위','기여도 1위 / 2위','인게임 1위 / 2위','총 수상'],rows.map(p=>`<tr><td><button class="text-button member-link" data-action="v2-award-detail" data-id="${p.id}">${X(p.name)}</button></td>${['damage','contribution','game'].map(k=>`<td class="center numeric">${p[k][0]} / ${p[k][1]}</td>`).join('')}<td class="center numeric"><strong>${p.total}</strong></td></tr>`),'hall-table');}
function topStats(boss){const samples=data.logs.filter(e=>e.stage===4&&e.boss===boss&&e.damage>0).sort((a,b)=>b.damage-a.damage).slice(0,data.rules.samples);const mean=samples.length?samples.reduce((s,e)=>s+Math.floor(e.damage/10000),0)/samples.length*10000:0;return {samples,mean,corrected:mean*data.rules.factor};}
function completeRates(){
 const levels=seasonLevels(data.rules).filter(l=>l.count),tops=data.bossSettings.map(b=>topStats(b.id));
 const factors=levels.map(l=>`<tr><th>${l.stage}단계<small>${l.start}–${l.count>=9999?'':l.end+'회차'}</small></th>${data.bossSettings.map(b=>`<td class="right numeric">${Number.isFinite(b.contribution[l.stage])?decimal(b.contribution[l.stage]):'—'}</td>`).join('')}</tr>`);
 const topRows=Array.from({length:data.rules.samples},(_,i)=>`<tr><th>${i+1}위</th>${tops.map(t=>`<td class="right numeric">${t.samples[i]?nf(Math.floor(t.samples[i].damage/10000)):'—'}</td>`).join('')}</tr>`);
 for(const key of ['mean','corrected'])topRows.push(`<tr class="average-row"><th>${key==='mean'?'평균':'보정 평균'}</th>${tops.map(t=>`<td class="right numeric">${t[key]?contributionText(t[key]):'—'}</td>`).join('')}</tr>`);
 const meta=`<div class="table-tools"><span>피해량 단위 만 · 상위 ${data.rules.samples}건</span><span>기준 기여도 ${nf(data.rules.baseline/10000)}만</span></div>`;
 return boardSection('단계별 보스 기여도 배율',rowTable(['단계·회차',...data.bossSettings.map(b=>`${b.id}넴`)],factors,'coefficient-table'),simpleButton('보정률 '+Math.round(data.rules.factor*100)+'%','v2-factor'))+boardSection('4단계 상위 기록',meta+rowTable(['순위',...data.bossSettings.map(b=>`${b.id}넴`)],topRows,'top-damage-table'));
}
function membershipPeriod(m){return (m.periods||[{from:m.joined?.slice(0,7),to:m.left?.slice(0,7)||null}]).map(p=>`${p.from?.replace('-','.')||'미상'}–${p.to?.replace('-','.')||'현재'}`).join(' / ');}
function chosung(name){const chars='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';return [...name].map(c=>{const n=c.charCodeAt(0)-44032;return n>=0&&n<11172?chars[Math.floor(n/588)]:c;}).join('');}
function matchName(m,query){const q=String(query).toLowerCase().replace(/\s/g,'');return [m.name,m.uid||'',chosung(m.name)].some(s=>s.toLowerCase().replace(/\s/g,'').includes(q));}
function completeRoster(alumni=false){
 const members=data.members.filter(m=>(alumni||m.status==='active')&&matchName(m,ext.rosterQuery)),page=pagedList(members,'roster');
 return `<div class="toolbar"><div class="toolbar-left"><input class="search-input" id="roster-search" data-input="v2-roster-query" aria-label="클랜원 검색" placeholder="이름 · 초성 · UID" value="${X(ext.rosterQuery)}"><span>${members.length}명</span></div>${simpleButton('추가','add-member')}</div>`+rowTable(['클랜원','상태',''],page.rows.map(m=>`<tr class="${m.status==='graduated'?'graduated':''}"><td>${memberLink(m)}</td><td class="center">${m.status==='active'?'재적':'탈퇴'}</td><td class="right">${simpleButton('정보','v3-member-info',m.id,'quiet')}</td></tr>`),'roster-table dense-table')+page.footer;
}

function fullClan(){return titleBar(ui.tabs.clan==='settings'?'설정':'클랜 DB')+pageTabs([['members','클랜원'],['alumni','역대 클랜원'],['rates','기여도'],['characters','캐릭터·초상화'],['settings','설정']])+({members:()=>completeRoster(false),alumni:()=>completeRoster(true),rates:completeRates,characters:characterLibrary,settings:completeSettings}[ui.tabs.clan]||(()=>completeRoster(false)))();}


function visibleTactics(){const source=ext.stage===3&&data.recommendations?.length?data.recommendations:data.tactics;return source.filter(t=>!t.deletedAt&&!t.hidden&&t.boss>0&&t.category!=='carry'&&t.boss>0&&t.stage===ext.stage&&(!ui.boss||t.boss===ui.boss)).sort((a,b)=>a.boss-b.boss||b.damage-a.damage);}
function completeBossFilter(){const values=[0,1,2,3,4,5,...(ui.section==='tactics'&&ui.tabs.tactics==='workspace'?[-1]:[])];return `<div class="filter-group boss-filter" role="group" aria-label="보스 필터">${values.map(n=>`<button data-action="boss-filter" data-value="${n}" class="${ui.boss===n?'active':''}" style="${n>0?bossStyle(n):''}" aria-pressed="${ui.boss===n}">${n===0?'전체':n===-1?'미분류':n+'넴'}</button>`).join('')}</div>`;}
function parseDelimited(text,delimiter=','){const rows=[],row=[];let cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()))rows.push([...row]);row.length=0;cell='';}else cell+=c;}row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);return rows;}
function tacticStarString(t){return t.stars.map(n=>`<span class="${[5,6].includes(Number(n))?'':'danger'}">${n||'?'}</span>`).join('');}
function tacticRows(t){if(!t.rows){let previous=Array(6).fill(false);t.rows=t.text.split('\n').filter(Boolean).map(text=>{const checked=inferChecked(text,previous,t);previous=checked;return {id:uid(),text,checked};});}return t.rows;}
function activeTactic(){const t=tacticById(ui.selectedTactic);return t&&!t.deletedAt?t:null;}
function fullTactics(){if(ui.tabs.tactics==='trash'&&!data.settings.editable)ui.tabs.tactics='workspace';if(ui.tabs.tactics==='planner'){ui.tabs.tactics='combos';ext.distributionOpen=true;findPlans();}const work=ui.tabs.tactics==='workspace';return titleBar('택틱',work&&data.settings.editable?simpleButton('삭제함','v2-tactic-trash')+simpleButton('택틱 추가','new-tactic','','primary'):'')+pageTabs([['combos','추천 조합'],['workspace','택틱 작업실'],['tools','이월 계산'],['external','외부 택틱'],['converter','택틱 변환기']])+({combos:recommendationRows,workspace:completeWorkspace,planner:completePlanner,tools:completeCarry,external:completeExternal,converter:completeConverter,trash:completeTrash}[ui.tabs.tactics]||recommendationRows)();}
function stageButtons(){const unlocked=data.bosses.some(b=>!b.locked&&b.stage>=4),stage3=data.rules.stage3Mode==='show'||data.rules.stage3Mode!=='hide'&&!unlocked;const stages=stage3?[3,4]:[4];if(stages.length===1)return '';return `<div class="filter-group" role="group" aria-label="조합 단계">${stages.map(stage=>`<button data-action="v2-combo-stage" data-value="${stage}" class="${ext.stage===stage?'active':''}">${stage}단계</button>`).join('')}</div>`;}
function recommendationRows(){
 if(ext.stage===3&&(data.rules.stage3Mode==='hide'||data.rules.stage3Mode==='auto'&&data.bosses.some(b=>!b.locked&&b.stage>=4)))ext.stage=4;
 if(ext.onlyPicks&&!selectedParties().length)ext.onlyPicks=false;let rows=visibleTactics();const early=ext.stage===3;if(ext.onlyPicks&&!early)rows=rows.filter(t=>ui.picks.includes(t.id));
 const toolbar=`<div class="toolbar"><div class="toolbar-left">${stageButtons()}${bossFilter()}</div><div class="toolbar-right">${early?'':simpleButton('추천 분배','v3-distribution','',ext.distributionOpen?'selected':'')}<span>${rows.length}개</span>${data.notices[ext.stage]?simpleButton('안내','v2-toggle-notice'):''}</div></div>${ext.noticeOpen&&data.notices[ext.stage]?`<div class="plain-notice">${X(data.notices[ext.stage]).replace(/\n/g,'<br>')}${data.settings.editable?simpleButton('안내 수정','v2-notice','','quiet'):''}</div>`:''}`;
 const page=pagedList(rows,'combos',8,'개');
 const headers=early?['보스','편성','성급','필요 시간','예상 이월','조작']:['선택','보스','편성','성급','손컨','TP','기대딜','택틱'];
 const body=page.rows.map(t=>`<tr class="${ui.picks.includes(t.id)?'picked':''}">${early?'':`<td><input type="checkbox" aria-label="${t.boss}넴 ${X(t.title)} 3타 선택" data-input="v2-pick-tactic" data-id="${t.id}" ${ui.picks.includes(t.id)?'checked':''}></td>`}<td><span class="boss-tag" style="${bossStyle(t.boss)}">${t.boss}넴</span><small>${early?'3단계':t.category==='tabi'?'타비비토':'택틱'}</small></td><td class="combo-party">${party(t)}</td><td class="center star-sequence">${tacticStarString(t)}</td>${early?`<td class="right numeric">${t.requiredSeconds==null?'—':t.requiredSeconds+'초'}</td><td class="right numeric">${t.remainingSeconds==null?'—':t.remainingSeconds+'초'}</td>`:`<td class="right ${t.hands?'danger':''}">${tacticHands(t)}</td><td class="right ${t.tp.includes('+')?'danger':''}">${X(t.tp||'—')}</td><td class="right numeric"><strong>${tacticDamageLabel(t)}</strong></td>`}<td>${simpleButton('열기','tactic-detail',t.id,'quiet')}</td></tr>`);
 return toolbar+recommendationDistribution()+rowTable(headers,body,early?'combo-table early-combo-table':'combo-table')+page.footer+completePlanStrip();
}

function selectedParties(){ui.picks=ui.picks.filter(id=>data.tactics.some(t=>t.id===id&&!t.deletedAt&&!t.hidden));return ui.picks.map(id=>data.tactics.find(t=>t.id===id));}
function partyConflicts(chosen){const seen=new Map(),conflicts=new Set();for(const t of chosen)for(const [i,c]of t.party.entries()){if(i===t.support)continue;if(seen.has(c))conflicts.add(c);seen.set(c,true);}return [...conflicts];}
function completePlanStrip(){const chosen=selectedParties();if(!chosen.length)return '';const conflict=partyConflicts(chosen);return `<div class="selection-strip"><strong>선택 ${chosen.length}/3</strong><span class="numeric">${decimal(chosen.reduce((sum,t)=>sum+t.damage,0))}억</span>${conflict.length?`<span class="danger">중복 ${X(conflict.join(', '))}</span>`:''}<span class="push"></span>${simpleButton(ext.onlyPicks?'전체 보기':'선택만 보기','v3-selected-only')}${simpleButton('복사','v2-copy-plan')}${simpleButton('비우기','clear-plan')}</div>`;}

function completePlanner(){ext.distributionOpen=true;if(!ext.foundPlans)findPlans();return recommendationRows();}

function findPlans(){const list=data.tactics.filter(t=>!t.hidden&&!t.deletedAt&&t.stage===4&&t.category!=='carry');const found=[];for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++)for(let k=j+1;k<list.length;k++){const group=[list[i],list[j],list[k]];if(!partyConflicts(group).length)found.push({ids:group.map(t=>t.id),damage:group.reduce((s,t)=>s+t.damage,0)});}ext.foundPlans=found.sort((a,b)=>b.damage-a.damage).slice(0,12);}
function foundPlanTable(){return boardSection('중복 없는 편성',rowTable(['조합','기대딜 합계','선택'],ext.foundPlans.map((p,i)=>`<tr><td>${p.ids.map(id=>{const t=data.tactics.find(t=>t.id===id);return t.boss+'넴 '+t.party[0];}).join(' / ')}</td><td class="right">${tacticDamageLabel(p)}</td><td>${simpleButton('선택','v2-use-plan',String(i),'quiet')}</td></tr>`)));}
const CARRY_TIME_RANGES=[['all','전체'],['20','20초대'],['30','30초대'],['40','40초대'],['50','50초+']];
function carryTimeRange(){return CARRY_TIME_RANGES.some(([key])=>key===ext.carryTimeRange)?ext.carryTimeRange:'all';}
function matchesCarryTimeRange(t){
 const range=carryTimeRange();if(range==='all')return true;
 const seconds=minimumCarry(t),start=Number(range);
 return Number.isFinite(seconds)&&seconds>=start&&(range==='50'||seconds<start+10);
}
function carryTimeFilter(){
 if(ext.workGroup!=='carry')return '';
 return `<select id="carry-time-range" class="carry-time-filter" data-input="v2-carry-time-range" aria-label="필요 이월시간으로 택틱 찾기">${CARRY_TIME_RANGES.map(([key,label])=>`<option value="${key}" ${carryTimeRange()===key?'selected':''}>${label}</option>`).join('')}</select>`;
}
function workspaceList(){if(ext.workGroup==='hidden'&&!data.settings.editable)ext.workGroup='main';return data.tactics.filter(t=>!t.deletedAt&&(ext.workGroup==='hidden'?t.hidden:!t.hidden&&t.category===ext.workGroup)&&(!ui.boss||(ui.boss===-1?!t.boss:t.boss===ui.boss))&&(ext.workGroup==='carry'||t.stage===ext.stage)&&(ext.workGroup!=='carry'||matchesCarryTimeRange(t))).sort((a,b)=>a.boss-b.boss||b.damage-a.damage);}
function workspaceListItem(item,selectedId){
 const carry=item.category==='carry',seconds=carry?minimumCarry(item):null,video=/^https?:\/\//i.test(item.video||'');
 const label=`${item.boss?item.boss+'넴':'미분류'} ${item.party.join(' ')}, 성급 ${item.stars.join('')}, 손컨 ${tacticHands(item)}, TP ${item.tp||'—'}, 기대딜 ${tacticDamageLabel(item)}`;
 return `<div class="work-list-row ${carry?'is-carry':''}" style="${item.boss?bossStyle(item.boss):'--boss:#aeb5c1'}">${carry?`<div class="work-list-carry">${seconds===null?'이월시간 미입력':seconds+'초 이월'}</div>`:''}<button type="button" class="work-item work-list-fields ${item.id===selectedId?'active':''}" data-action="v2-select-tactic" data-id="${item.id}" aria-label="${X(label)}"><span class="work-list-boss">${item.boss?item.boss+'넴':'미분류'}</span><strong class="work-list-party">${X(item.party.join(' '))}</strong><span class="work-list-stars">${tacticStarString(item)}</span><small class="work-list-hands ${item.hands?'danger':''}"><span class="work-field-label">손컨 </span>${tacticHands(item)}</small><small class="work-list-tp ${item.tp.includes('+')?'danger':''}"><span class="work-field-label">TP </span>${X(item.tp||'—')}</small><span class="work-list-damage"><span class="work-field-label">기대딜 </span>${tacticDamageLabel(item)}</span></button>${video?`<a class="button work-list-video" href="${X(item.video)}" target="_blank" rel="noopener noreferrer" aria-label="${X(item.boss+'넴 '+item.party.join(' ')+' 원본 영상')}">영상</a>`:'<span class="work-list-video missing" aria-label="등록된 영상 없음">—</span>'}</div>`;
}
function completeWorkspace(){
 ext.stage=4;const list=workspaceList(),t=list.find(t=>t.id===ui.selectedTactic)||list[0];if(t)ui.selectedTactic=t.id;
 const emptyMessage=ext.workGroup==='carry'&&carryTimeRange()!=='all'?'해당 시간대의 이월 택틱이 없습니다.':'택틱을 추가하세요.';
 const categories=[['main','택틱정리'],['tabi','타비비토'],['carry','이월 택틱'],['hidden','숨김']].filter(([key])=>(key!=='carry'||data.rules.carryVisible)&&(key!=='hidden'||data.settings.editable));
 const groupTacticCount=key=>data.tactics.filter(t=>!t.deletedAt&&(key==='hidden'?t.hidden:!t.hidden&&t.category===key)&&(key==='carry'||t.stage===4)).length;
 const navigation=`<div class="workspace-toolbar"><div class="workspace-navigation" role="group" aria-label="택틱 분류">${categories.map(([key,name])=>`<button class="button ${ext.workGroup===key?'selected':''}" data-action="v2-work-group" data-value="${key}">${name}<span class="count">${groupTacticCount(key)}</span></button>`).join('')}</div><div class="workspace-boss-filters">${bossFilter()}</div></div>`;
 return navigation+`<div class="workbench"><aside class="work-library ${ui.libraryOpen?'expanded':''}"><div class="sheet-heading"><h2>택틱 ${list.length}</h2>${carryTimeFilter()}<button class="text-button mobile-only" data-action="toggle-library" aria-expanded="${ui.libraryOpen}">${ui.libraryOpen?'목록 닫기':'목록 열기'}</button></div><div class="work-list"><div class="work-list-column-heads" aria-hidden="true"><div class="work-list-fields"><span>보스</span><span>캐릭터명</span><span>성급</span><span>손컨</span><span>TP</span><span>기대딜</span></div><span>영상</span></div>${list.map(item=>workspaceListItem(item,t?.id)).join('')||'<p class="no-rows">택틱 없음</p>'}</div></aside><section class="work-editor" style="${t?.boss?bossStyle(t.boss):'--boss:#aeb5c1'}">${t?workEditor(t):`<p class="no-rows">${emptyMessage}</p>`}</section></div>`;
}
function richInstruction(text){return X(text).replace(/(AUTO\s*(?:ON|온)|\bON\b|\bSET\b)/g,'<span class="action-on">$1</span>').replace(/(AUTO\s*(?:OFF|오프)|\bOFF\b)/g,'<span class="action-off">$1</span>').replace(/(한번만)/g,'<span class="action-once">$1</span>');}
function renderTacticGrid(t,editing=false){tacticProgress();const rows=tacticRows(t),base=t.duration||90;return `<div class="table-wrap tactic-grid-wrap tactic-layout-inline"><table class="set-grid" data-tactic-id="${t.id}" tabindex="0" aria-label="택틱 본문"><colgroup>${Array(6).fill('<col class="set-check-col">').join('')}<col><col class="set-tools-col"></colgroup><thead><tr>${t.party.map((name,i)=>`<th scope="col" title="${X(name)}"><span class="set-character-face">${portraitHtml(name,t.stars[i])}</span></th>`).join('')}<th class="set-auto" scope="col" title="AUTO" aria-label="AUTO">A</th><th>조작 · 시간</th><th></th></tr></thead><tbody>${rows.map((row,i)=>`<tr data-row="${row.id}" class="${ext.tacticCursor?.[t.id]===row.id?'tactic-active-row':''}" aria-selected="${ext.tacticCursor?.[t.id]===row.id}">${Array.from({length:6},(_,j)=>`<td class="set-check ${j===5?'auto-cell':''}"><input type="checkbox" aria-label="${i+1}행 ${j===5?'AUTO':X(t.party[j])} SET" data-input="v2-row-check" data-row="${row.id}" data-column="${j}" ${row.checked[j]?'checked':''} ${!editing||!data.settings.editable?'disabled':''}></td>`).join('')}<td class="instruction-cell">${editing?`<textarea aria-label="${i+1}행 택틱" data-input="v2-row-text" data-row="${row.id}" rows="1">${X(row.text)}</textarea>`:`<div>${legacyTools.richLine(row,t.party,data.characters,ui.carry,base)}</div>`}</td><td>${editing?`<button data-action="v2-delete-row" data-id="${row.id}" aria-label="${i+1}행 삭제">×</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function tacticReadingHeader(t){
 const carry=t.category==='carry',note=displayTacticNote(t),needed=carry?minimumCarry(t):null,warning=carry&&needed!==null&&ui.carry<needed;
 const memo=note?`<div class="tactic-note tactic-reading-note">${X(note).replace(/\n/g,'<br>')}</div>`:'';
 const received=carry?`<section class="carry-summary"><div><span>필요 이월</span><strong>${needed===null?'—':needed+'초'}</strong></div><div class="field"><label for="carry-main-received">받은 이월 · 초</label><input id="carry-main-received" type="number" min="1" max="90" inputmode="numeric" data-input="ops-carry-received" value="${ui.carry}"></div><p class="carry-warning danger" ${warning?'':'hidden'}>필요 이월보다 짧습니다.</p></section>`:'';
 const links=[...(t.video?[{label:'원본 영상',url:t.video}]:[]),...(t.links||[])];
 const video=links.length?`<div class="tactic-intro-links">${links.map(link=>`<a class="button" href="${X(link.url)}" target="_blank" rel="noopener noreferrer">${X(link.label)}</a>`).join('')}</div>`:'';
 return `<div class="work-editor-head tactic-reading-head ${carry?'is-carry':''}">${carry?`<div class="tactic-intro-top">${received}</div>`:''}<div class="tactic-summary-row"><div class="tactic-identity"><h2>${t.boss?t.boss+'넴 · '+X(bossBy(t.boss).name):'미분류'}</h2><div class="tactic-metadata"><span class="${t.hands?'danger':''}">손컨 ${tacticHands(t)}</span> · <span class="${t.tp.includes('+')?'danger':''}">TP ${X(t.tp||'—')}</span> · <span>기대딜 <strong>${tacticDamageLabel(t)}</strong></span></div>${video}</div><div class="tactic-header-party">${party(t)}</div></div>${memo}${data.settings.editable?`<div class="work-actions">${simpleButton('편성 수정','edit-tactic',t.id)}${simpleButton(t.hidden?'다시 표시':'숨기기','hide-tactic',t.id)}${simpleButton('복제','duplicate-tactic',t.id)}${simpleButton('삭제','delete-tactic',t.id,'danger')}</div>`:''}</div>`;
}
function workEditor(t){
 const carry=t.category==='carry';
 return tacticReadingHeader(t)+`<div class="work-control-row ${carry?'is-carry':''}">${carry?'':`<div class="carry-inline"><label for="workspace-carry">이월 받은 시간</label><input id="workspace-carry" data-input="v2-work-carry" value="${fmtTime(ui.carry)}" inputmode="numeric"><button class="button" data-action="v2-carry-original">초기화</button><button class="button" data-action="v2-work-estimate">이월 계산</button></div>`}<div>${simpleButton('본문 복사','copy-tactic',t.id)}${simpleButton('SET 포함 복사','v2-copy-set')}${simpleButton(ext.workEditing?'편집 완료':'표 편집','v2-edit-grid','','primary')}</div></div>${ext.showEstimator?completeCarry(true):''}${renderTacticGrid(t,ext.workEditing)}<div class="work-bottom"><div>${ext.workEditing?simpleButton('행 추가','v2-add-row')+simpleButton('여러 행 붙여넣기','v2-paste-rows')+simpleButton('문장으로 SET 다시 계산','v2-restate'):''}${simpleButton('실행 취소','v2-row-undo')}${simpleButton('다시 실행','v2-row-redo')}</div><span id="tactic-save-state">${ext.workEditing?'Enter 다음 행 · Shift+Enter 줄바꿈':''}</span></div>${ext.workGroup==='carry'?`<div class="work-bottom">${simpleButton('이월 시트 가져오기','v2-import-carry')}${simpleButton('양식 받기','v2-carry-template')}</div>`:''}`;
}

function adjustedWithBase(text,remaining,base=90){return String(text).replace(/\b(\d{1,2}):(\d{2})\b/g,(all,m,s)=>{const time=Number(m)*60+Number(s);if(time>base||Number(s)>=60)return all;const shifted=time+remaining-base;return shifted>0?fmtTime(shifted):'—';});}
function fullTacticDetail(id){const t=tacticById(id);if(!t)return;ui.selectedTactic=t.id;openDrawer(`${t.boss}넴 ${tacticDamageLabel(t)}`,`${party(t)}<div class="tactic-metadata"><span class="${t.hands?'danger':''}">손컨 ${tacticHands(t)}</span> · <span class="${t.tp.includes('+')?'danger':''}">TP ${X(t.tp||'—')}</span></div><div class="carry-inline"><label for="detail-carry">이월 받은 시간</label><input id="detail-carry" data-input="v2-detail-carry" value="${fmtTime(ui.carry)}" data-id="${t.id}"></div><div id="detail-timeline">${simpleTacticTimeline(t)}</div>${t.note?`<p class="tactic-note">${X(displayTacticNote(t))}</p>`:''}${t.video?`<a href="${X(t.video)}" class="plain-link" target="_blank" rel="noopener noreferrer">원본 영상</a>`:''}`,simpleButton('복사','copy-tactic',t.id)+(t.recommendationOnly?simpleButton('닫기','close-drawer'):simpleButton('작업실에서 열기','v2-open-workspace',t.id,'primary')),'',true);}

function simpleTacticTimeline(t){return rowTable(['남은 시간','조작'],tacticRows(t).map(r=>{const line=adjustedWithBase(r.text,ui.carry,t.duration||90),match=line.match(/^(\d+:\d{2}|—)\s*(.*)$/);return `<tr><td class="mono">${match?match[1]:'—'}</td><td>${richInstruction(match?match[2]:line)}</td></tr>`;}),'timeline-table');}
function editCompleteTactic(id=null){
 if(!ensureEdit())return;
 const t=data.tactics.find(t=>t.id===id)||{id:'',boss:ui.boss>0?ui.boss:0,stage:4,damage:0,hands:0,tp:'',party:data.characters.slice(0,5).map(c=>c.name),stars:[5,5,5,5,5],support:-1,category:ext.workGroup==='tabi'?'tabi':ext.workGroup==='carry'?'carry':'main',duration:90,text:'1:30 AUTO 오프',note:'',video:'',links:[]};
 openDrawer(t.id?'택틱 설정':'택틱 추가',`<input name="tacticId" type="hidden" value="${t.id}"><input name="stage" type="hidden" value="4"><div class="carry-tactic-fields" ${t.category==='carry'?'':'hidden'}><div class="field"><label for="tactic-required-carry">필요 이월 · 초</label><input id="tactic-required-carry" name="requiredCarrySeconds" type="number" min="1" max="90" step="1" value="${minimumCarry(t)??''}" inputmode="numeric"></div><div class="field"><label for="tactic-duration">원문 시작시간</label><input id="tactic-duration" name="duration" value="${fmtTime(t.duration||90)}" inputmode="numeric"></div></div><div class="field-row"><div class="field"><label for="tactic-boss">보스</label><select id="tactic-boss" name="boss"><option value="0">미분류</option>${data.bossSettings.map(b=>`<option value="${b.id}" ${t.boss===b.id?'selected':''}>${b.id}넴 · ${X(b.name)}</option>`).join('')}</select></div><div class="field"><label for="tactic-category">분류</label><select id="tactic-category" name="category">${[['main','택틱정리'],['tabi','타비비토'],['carry','이월 택틱']].map(([key,label])=>`<option value="${key}" ${t.category===key?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="tactic-condition-fields"><div class="field"><label for="tactic-damage">기대딜</label><input type="hidden" name="damageUnit" value="100000000"><input id="tactic-damage" name="damage" type="number" min="0" step="any" value="${t.damage}" required></div><div class="field"><label for="tactic-hands">손컨</label><input id="tactic-hands" name="hands" type="number" min="0" step="0.5" value="${t.hands??''}"></div><div class="field"><label for="tactic-tp">TP</label><input id="tactic-tp" name="tp" value="${X(t.tp)}"></div></div><div class="tactic-lineup-form">${Array.from({length:5},(_,i)=>`<div><label for="party-${i}">${i+1}번</label><select id="party-${i}" name="party-${i}">${data.characters.map(c=>`<option value="${X(c.name)}" ${c.name===t.party[i]?'selected':''}>${X(c.name)}</option>`).join('')}</select><select name="star-${i}" aria-label="${i+1}번 성급">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===Number(t.stars[i])?'selected':''}>${n}성</option>`).join('')}</select></div>`).join('')}</div><details class="form-fold" open><summary>본문 붙여넣기</summary><textarea id="tactic-text" name="text" aria-label="택틱 본문" rows="10">${X(t.text)}</textarea></details><details class="form-fold"><summary>메모·영상·대여</summary><div class="field"><label for="tactic-note">육성 조건·메모</label><textarea id="tactic-note" name="note" rows="3">${X(displayTacticNote(t))}</textarea></div><div class="field"><label for="tactic-video">원본 영상</label><input id="tactic-video" name="video" type="url" value="${X(t.video||'')}"></div><div class="field"><label for="tactic-support">대여 캐릭터</label><select id="tactic-support" name="support"><option value="-1" ${t.support<0?'selected':''}>없음</option>${[0,1,2,3,4].map(i=>`<option value="${i}" ${i===t.support?'selected':''}>${i+1}번째</option>`).join('')}</select></div></details>`,`<button type="button" class="button" data-action="close-drawer">취소</button><button type="submit" class="button primary">저장</button>`,'',true,'v2-tactic');
}

function saveCompleteTactic(form){const fd=new FormData(form),id=fd.get('tacticId'),duration=timeToSec(fd.get('duration'));if(!Number.isFinite(duration)||duration<=0||duration>130){toast('원본 전투시간을 확인하세요.');return;}checkpoint();const old=data.tactics.find(t=>t.id===id),text=String(fd.get('text')),value={id:id||uid(),boss:Number(fd.get('boss')),stage:4,category:String(fd.get('category')),duration,requiredCarrySeconds:fd.get('requiredCarrySeconds')?Number(fd.get('requiredCarrySeconds')):null,damage:Number(fd.get('damage'))/(fd.get('damageUnit')==='1'?100000000:1),hands:Number(fd.get('hands')||0),tp:String(fd.get('tp')),party:Array.from({length:5},(_,i)=>String(fd.get('party-'+i))),stars:Array.from({length:5},(_,i)=>Number(fd.get('star-'+i))),support:Number(fd.get('support')),text,note:String(fd.get('note')),video:String(fd.get('video')),hidden:old?.hidden||false,links:old?.links||[],rows:old?.text===text?old.rows:null};value.title=value.party.join(' ');if(old)Object.assign(old,value);else data.tactics.push(value);ui.selectedTactic=value.id;ext.stage=value.stage;ext.workGroup=value.category;ext.carryTimeRange='all';ui.carry=value.duration;ui.boss=0;persist();closeDrawer();nav('tactics','workspace');toast('택틱 저장',true);}
function completeTrash(){const trashed=data.tactics.filter(t=>t.deletedAt);return `<div class="toolbar"><h2>삭제한 택틱 ${trashed.length}</h2>${simpleButton('작업실','v2-back-workspace')}</div>`+rowTable(['보스','편성','분류','삭제일','복원'],trashed.map(t=>`<tr><td>${t.boss?t.boss+'넴':'미분류'}</td><td>${X(t.party.join(' '))}</td><td>${t.category==='carry'?'이월 택틱':t.category==='tabi'?'타비비토':'택틱정리'}</td><td>${new Date(t.deletedAt).toLocaleDateString('ko-KR')}</td><td>${simpleButton('복원','v2-restore-tactic',t.id)}</td></tr>`));}
function completeCarry(embedded=false){const b=bossBy(activeTactic()?.boss||ui.boss||1),fields=[['estimate-hp','보스 남은 HP',b.hp],['estimate-first','선통 예상 피해량',0],['estimate-second','후통 예상 피해량',300000000],['estimate-seconds','후통 전투시간 · 초',90]];return `<section class="carry-calculation ${embedded?'embedded':''}"><div class="sheet-heading"><h2>선통·후통 예상 이월</h2>${embedded?simpleButton('닫기','v2-work-estimate'):''}</div><div class="estimate-fields">${fields.map(([id,label,val])=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" data-input="v2-estimate" value="${nf(ext.estimatorInputs?.[id]??val)}" inputmode="numeric"></div>`).join('')}</div><div class="estimate-result"><span>예상 이월 시간</span><strong id="estimate-result" class="mono">—</strong><span id="estimate-error"></span>${simpleButton('택틱에 적용','v2-apply-estimate','','primary')}</div></section>${embedded?'':`<section class="carry-calculation"><h2>격파 순간 남은 시간으로 계산</h2><div class="remaining-calculation"><label for="carry-remaining">남은 시간</label><input id="carry-remaining" data-input="v2-remaining-calculator" value="0:36" inputmode="numeric"><span>+ 20초 =</span><strong class="mono" id="carry-result">0:56</strong>${simpleButton('적용','v2-apply-remaining')}</div></section>`}`;}
function estimateResult(){const values=Object.fromEntries(['hp','first','second','seconds'].map(key=>[key,numberValue(document.getElementById('estimate-'+key)?.value)]));return engineEstimate(values);}
function updateEstimator(){const resultEl=document.getElementById('estimate-result');if(!resultEl)return;const result=estimateResult();resultEl.textContent=result.error?'—':fmtTime(result.seconds);document.getElementById('estimate-error').textContent=result.error||'';}
function completeExternal(){return `<div class="external-controls"><div class="field"><label for="external-base">원본 전투시간</label><input id="external-base" data-input="v2-external" value="${fmtTime(ext.externalBase||90)}" inputmode="numeric"></div><div class="field"><label for="external-carry">이월 받은 시간</label><input id="external-carry" data-input="v2-external" value="${fmtTime(ext.externalSeconds||90)}" inputmode="numeric"></div>${simpleButton('초기화','v2-external-reset')}${simpleButton('복사','copy-external')}</div><div class="external-columns"><div class="field"><label for="external-text">원문</label><textarea id="external-text" data-input="v2-external" rows="18" spellcheck="false">${X(ext.externalText||'')}</textarea></div><div class="field"><label>이월 적용</label><pre id="external-output" class="code-output"></pre></div></div><p class="field-help">행동·순서·줄바꿈은 유지하며 시간만 변경합니다. 전투가 끝난 뒤의 시각은 —로 표시합니다.</p>`;}
function updateExternal(){const source=document.getElementById('external-text'),output=document.getElementById('external-output');if(!source||!output)return;ext.externalText=source.value;ext.externalBase=timeToSec(document.getElementById('external-base').value);ext.externalSeconds=timeToSec(document.getElementById('external-carry').value);if(!(ext.externalBase>0&&ext.externalSeconds>0&&ext.externalSeconds<=ext.externalBase)){output.textContent='입력한 시간을 확인하세요.';return;}output.textContent=adjustedWithBase(source.value,ext.externalSeconds,ext.externalBase);}
function completeConverter(){return `<div class="converter-lineup">${Array.from({length:5},(_,i)=>`<div><label for="convert-name-${i}">${i+1}번 캐릭터</label><select id="convert-name-${i}" data-input="v2-converter"><option value="">선택</option>${data.characters.map(c=>`<option value="${X(c.name)}" ${ext.converterNames[i]===c.name?'selected':''}>${X(c.name)}</option>`).join('')}</select><input id="convert-alias-${i}" data-input="v2-converter" aria-label="${i+1}번 원문 이름" placeholder="원문 이름·별칭" value="${X(ext.converterAliases[i]||'')}"></div>`).join('')}</div><div class="external-columns"><div class="field"><label for="converter-source">해외 택틱 원문</label><textarea id="converter-source" data-input="v2-converter" rows="16" spellcheck="false">${X(ext.converterRaw)}</textarea></div><div class="field"><label>정리 결과</label><pre id="converter-output" class="code-output"></pre><div id="converter-warnings"></div></div></div><div class="toolbar"><div class="toolbar-left">${simpleButton('결과 복사','v2-copy-converted')}${simpleButton('SET 포함 복사','v2-copy-converted-set')}${simpleButton('작업실에 등록','v2-save-converted','','primary')}</div><div class="toolbar-right">${simpleButton('초기화','v2-reset-converter')}</div></div>`;}
function refreshConverter(){const source=document.getElementById('converter-source');if(!source)return;ext.converterRaw=source.value;ext.converterNames=Array.from({length:5},(_,i)=>document.getElementById('convert-name-'+i).value);ext.converterAliases=Array.from({length:5},(_,i)=>document.getElementById('convert-alias-'+i).value);if(!source.value.trim()){document.getElementById('converter-output').textContent='';document.getElementById('converter-warnings').innerHTML='';return;}const result=convertForeignTactic(source.value,ext.converterNames,ext.converterAliases,data.bossSettings.map(b=>b.name),data.characters.map(c=>c.name));ext.converterResult=result;document.getElementById('converter-output').textContent=result.text;document.getElementById('converter-warnings').innerHTML=(result.warnings||[]).map(w=>`<p class="field-help danger">${X(w)}</p>`).join('');}
function saveGridText(t){t.text=tacticRows(t).map(r=>r.text).join('\n');t.title=t.party.join(' ');persist();const status=document.getElementById('tactic-save-state');if(status)status.textContent='저장됨';}
function rememberRows(t){ext.rowUndo.push({id:t.id,rows:structuredClone(tacticRows(t))});if(ext.rowUndo.length>60)ext.rowUndo.shift();ext.rowRedo=[];}
function inferChecked(text,previous,t){const checked=[...previous];const auto=text.match(/AUTO\s*(?:먼저\s*)?(ON|OFF|온|오프)/i);if(auto)checked[5]=/^(ON|온)$/i.test(auto[1]);if(/전원\s*(SET|ON)/.test(text))for(let i=0;i<5;i++)checked[i]=true;for(const [i,name]of t.party.entries()){if(!text.includes(name))continue;const at=text.indexOf(name),tail=text.slice(at+name.length);if(/^[^\n]*?(OFF|오프)/.test(tail))checked[i]=false;else if(/^[^\n]*?(SET|ON|온|한번만)/.test(tail))checked[i]=true;}return checked;}
function pasteRows(text,t){const lines=String(text).replace(/\r/g,'').split('\n').filter(Boolean),rows=[];let previous=Array(6).fill(false);for(const line of lines){const cells=line.split('\t');let checked,body;if(cells.length>=7&&cells.slice(0,6).every(v=>/^(true|false|0|1|o|x|⭕|❌)$/i.test(v.trim()))){checked=cells.slice(0,6).map(v=>/^(true|1|o|⭕)$/i.test(v.trim()));body=cells.slice(6).join('\t');}else{body=line;checked=inferChecked(line,previous,t);}rows.push({id:uid(),text:body,checked});previous=checked;}return rows;}
function openPasteRows(){if(!ensureEdit())return;openDrawer('여러 행 붙여넣기',`<div class="field"><label for="paste-grid-source">택틱 또는 SET 6칸이 포함된 표</label><textarea id="paste-grid-source" rows="13"></textarea></div><label class="inline-check"><input id="paste-grid-replace" type="checkbox">현재 본문 교체</label>`,simpleButton('취소','close-drawer')+simpleButton('적용','v2-commit-paste','','primary'),'',true);}
async function xlsxRows(file){const zip=await JSZip.loadAsync(file),parser=new DOMParser(),sharedFile=zip.file('xl/sharedStrings.xml');let shared=[];if(sharedFile){const xml=parser.parseFromString(await sharedFile.async('string'),'application/xml');shared=[...xml.getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join(''));}const sheets=Object.keys(zip.files).filter(name=>/^xl\/worksheets\/sheet\d+\.xml$/.test(name)).sort();if(!sheets.length)throw new Error('시트 없음');const xml=parser.parseFromString(await zip.file(sheets[0]).async('string'),'application/xml');return [...xml.getElementsByTagName('row')].map(row=>{const values=[];for(const c of row.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A1',letters=ref.match(/[A-Z]+/)[0];let col=0;for(const char of letters)col=col*26+char.charCodeAt(0)-64;const type=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent||'';values[col-1]=type==='s'?shared[Number(v)]||'':type==='inlineStr'?[...c.getElementsByTagName('t')].map(t=>t.textContent).join(''):v;}return values;});}
function parseCarrySheet(rows){const header=rows[0].map(v=>String(v||'').trim().replace(/\s/g,'')),index=names=>header.findIndex(h=>names.includes(h)),bossCol=index(['보스','네임드','넴']),partyCol=index(['편성','캐릭터','조합']),bodyCol=index(['본문','택틱','내용']);if(bossCol<0||partyCol<0||bodyCol<0)throw new Error('첫 행에 보스·편성·본문 열이 필요합니다.');const cell=(row,names)=>{const i=index(names);return i<0?'':String(row[i]||'');};return rows.slice(1).filter(row=>row[bodyCol]).map(row=>({boss:Number(String(row[bossCol]).replace(/\D/g,''))||0,party:String(row[partyCol]).split(/[,/·\s]+/).filter(Boolean).slice(0,5),text:String(row[bodyCol]),stars:cell(row,['성급']).replace(/\D/g,'').split('').slice(0,5).map(Number),damage:parseFloat(cell(row,['기대딜','피해량']))||0,hands:parseFloat(cell(row,['손컨','손컨횟수']))||0,tp:cell(row,['TP','TP조건']),duration:timeToSec(cell(row,['시간','원본시간','전투시간'])||'1:00'),video:cell(row,['영상','원본영상']),note:cell(row,['비고','메모'])}));}
