function completeLogPreview(){
 const form=drawer.querySelector('form[data-form="v2-log"]');if(!form)return;
 syncAttackEntry(form);if(!form.querySelector('[name="boss"]')?.value){document.getElementById('log-preview').textContent='';return;}const fd=new FormData(form),state=attackEntryState(fd),b=state.boss,before=state.old?.before??b.hp,damage=state.damage,actual=Math.min(damage||0,before),remaining=timeToSec(fd.get('remaining'));
 document.getElementById('log-boss-preview').innerHTML=`<span>${state.stage}단계 ${state.old?.lap||b.lap}회차</span><strong class="numeric">HP ${nf(before)}</strong>`;
 document.getElementById('log-preview').innerHTML=`<dl class="preview-values"><div><dt>실제 피해량</dt><dd>${nf(actual)}</dd></div><div><dt>공격 후 HP</dt><dd>${nf(Math.max(0,before-(damage||0)))}</dd></div>${damage>=before&&Number.isFinite(remaining)?`<div><dt>이월</dt><dd>${fmtTime(Math.min(90,remaining+20))}</dd></div>`:''}</dl>`;
}

function saveCompleteLog(form){const fd=new FormData(form),id=String(fd.get('logId')||''),old=data.logs.find(e=>e.id===id),entry=attackEntryState(fd),damage=entry.damage,memberId=String(fd.get('memberId')),boss=Number(fd.get('boss')),day=Number(fd.get('day')),carry=fd.has('usesCarry'),bonus=numberValue(fd.get('bonus')||0);if(!Number.isSafeInteger(bonus)){toast('가산점은 양수 또는 음수의 정수로 입력하세요.');return false;}if(!Number.isSafeInteger(damage)||damage<=0){toast('피해량은 1 단위의 양의 정수로 입력하세요.');return false;}if(data.dayClosures.some(d=>d.day===day)){toast('마감을 취소한 뒤 수정하세요.');return false;}if(!old&&bossBy(boss).locked){toast(bossBy(boss).lockedReason);return false;}if(!memberSeasonActive(currentMember(memberId),day)){toast('참가 일차에 해당하지 않는 클랜원입니다.');return false;}const daily=data.logs.filter(e=>e.day===day&&e.memberId===memberId&&e.id!==id),used=daily.filter(e=>!e.carry).length,pending=daily.filter(e=>e.kill&&!e.carry&&!daily.some(c=>c.carryFrom===e.id)).length;if(!old&&!carry&&used>=data.rules.daily){toast('기본 타수를 모두 사용했습니다.');return false;}if(!old&&carry&&!pending){toast('사용할 이월이 없습니다.');return false;}const remaining=String(fd.get('remaining')||''),seconds=remaining?timeToSec(remaining):NaN;if(remaining&&!(seconds>=0&&seconds<=90)){toast('남은 시간을 확인하세요.');return false;}if(!old){
  const time=String(fd.get('gameAt')||'').trim();
  const suspect=data.logs.filter(e=>e.day===day&&e.memberId===memberId&&Number(e.boss)===boss&&Number(e.damage)===damage&&(!time||!e.gameAt||e.gameAt===time));
  if(suspect.length&&!confirm('동일한 클랜원·보스·피해량의 공격이 오늘 '+suspect.length+'건 이미 기록돼 있습니다. 실제로 별도의 공격을 한 것이 맞나요?'))return false;
  if(form.dataset.logSubmitPending==='1')return false;
  form.dataset.logSubmitPending='1';
 }
 checkpoint();const value={memberId,boss,day,damage,damageMode:entry.automatic?'max':'manual',carry,usesCarry:carry,note:String(fd.get('note')||''),bonus:bonus/10000,gameAt:String(fd.get('gameAt')||''),carrySeconds:Number.isFinite(seconds)?Math.min(90,seconds+20):old?.carrySeconds||0};if(old)Object.assign(old,value);else data.logs.push({id:uid(),seq:Math.max(0,...data.logs.map(e=>e.seq))+1,...value});recalculateSeason();persist();if(drawer.open)closeDrawer();render();toast(old?'기록 수정':'기록 등록',true);return true;}
function deleteCompleteLog(id){if(!ensureEdit())return false;if(!data.logs.some(e=>e.id===id)){toast('공격 기록을 찾지 못했습니다.');return false;}checkpoint();data.logs=data.logs.filter(e=>e.id!==id);recalculateSeason();persist();if(drawer.open)closeDrawer();render();toast('기록 삭제',true);return true;}
function editCompleteMember(id=null){if(!ensureEdit())return;const m=data.members.find(m=>m.id===id)||{id:'',name:'',uid:'',status:'active',joined:ui.month+'-01',left:'',periods:[{from:ui.month,to:null}],note:''},membership=data.memberships[m.id]||{from:ui.day,to:data.rules.days};openDrawer(m.id?'클랜원 수정':'클랜원 추가',`<input type="hidden" name="memberId" value="${m.id}"><div class="field-row"><div class="field"><label for="member-name">닉네임</label><input id="member-name" name="name" required value="${X(m.name)}"></div><div class="field"><label for="member-uid">UID</label><input id="member-uid" name="uid" value="${X(m.uid)}"></div></div><div class="field-row"><div class="field"><label for="member-status">상태</label><select id="member-status" name="status"><option value="active" ${m.status==='active'?'selected':''}>재적</option><option value="graduated" ${m.status!=='active'?'selected':''}>탈퇴</option></select></div><div class="field"><label for="member-joined">최초 가입일</label><input id="member-joined" name="joined" type="date" value="${m.joined}" required></div></div><div class="field-row"><div class="field"><label for="member-from">이번 달 참가 시작</label><input id="member-from" name="fromDay" type="number" min="1" max="${data.rules.days}" value="${membership.from}"></div><div class="field"><label for="member-to">이번 달 참가 종료</label><input id="member-to" name="toDay" type="number" min="1" max="${data.rules.days}" value="${membership.to}"></div></div><div class="sheet-heading"><h3>소속 이력</h3>${simpleButton('구간 추가','v2-add-membership-period')}</div><div id="membership-periods">${(m.periods||[]).map((p,i)=>periodFields(p,i)).join('')}</div><div class="field"><label for="member-note">메모</label><textarea name="note" id="member-note" rows="3">${X(m.note)}</textarea></div>`,`<button type="button" class="button" data-action="close-drawer">취소</button><button type="submit" class="button primary">저장</button>`,'',true,'v2-member');}
