  const tabs=admin?[['display','화면'],['rules','월별 보스·규칙'],['future','미래 보스'],['copy','메뉴·문구'],['data','월·백업'],['access','공유·권한'],['links','자료 링크']]:[['display','화면'],['future','미래 보스'],['access','공유·권한']];
