function historyMonths(){return [...new Set([...(data.history||[]).map(h=>h.month),...Object.keys(data.seasons)])].sort().reverse();}
function historySeason(month){return month===ui.month?data:data.seasons[month];}
function historyResult(month){
  const stored=(data.history||[]).find(h=>h.month===month),season=historySeason(month);
  if(!season)return {month,rank:stored?.clanRank,count:stored?.memberCount||0,winners:Object.fromEntries(RESULT_METRICS.map(([metric])=>[metric,(stored?.winners?.[metric]||[]).map(name=>({name}))])),sealed:true,stored};
  const summary=seasonSummary(month);return {month,rank:season.result.rank??stored?.clanRank,count:summary.count,winners:season.result.winners||summary.winners,sealed:!!season.result.sealed,changed:season.result.sealed&&season.result.fingerprint!==resultFingerprint(season.logs),stored};
}
completeHistory=()=>rowTable(['월','클랜 순위','참가','인게임 1·2위','기여도 1·2위','피해량 1·2위','결과'],historyMonths().map(month=>{
  const result=historyResult(month),season=historySeason(month);
  return `<tr><td>${month.replace('-','.')}</td><td>${adminMode()?`<button class="text-button" data-action="u-history-rank" data-id="${month}">${result.rank?result.rank+'위':'입력'}</button>`:result.rank?result.rank+'위':'—'}</td><td class="center">${result.count||'—'}</td>${RESULT_METRICS.map(([metric])=>`<td class="winner-cell">${winnerText(result.winners,metric)}</td>`).join('')}<td>${season&&adminMode()?simpleButton(result.changed?'다시 확정':result.sealed?'확정됨':'결과 확정','u-confirm-result',month,result.sealed?'quiet':'primary'):`<span class="result-status ${result.sealed?'sealed':''}">${result.sealed?'확정':'미확정'}</span>`}</td></tr>`;
}),'history-table exact-table');
function awardRows(){
  const map=new Map((data.awards||[]).map(p=>[p.name,{...structuredClone(p),id:data.members.find(m=>m.name===p.name)?.id||p.name}]));
  for(const month of Object.keys(data.seasons)){
    if((data.history||[]).some(h=>h.month===month))continue;
    const result=historySeason(month).result;if(!result.sealed||!result.winners)continue;
    for(const [metric]of RESULT_METRICS)for(const [index,person]of(result.winners[metric]||[]).entries()){
      if(!map.has(person.name))map.set(person.name,{id:person.id,name:person.name,game:[0,0],contribution:[0,0],damage:[0,0],total:0});
      const row=map.get(person.name);row[metric][index]++;row.total++;
    }
  }
  return [...map.values()].sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name,'ko'));
}
completeHall=()=>`<div class="table-tools"><span>확정한 월별 결과 기준</span></div>`+rowTable(['클랜원','인게임 1위 / 2위','기여도 1위 / 2위','피해량 1위 / 2위','총 수상'],awardRows().map(p=>`<tr><td><button class="text-button member-link" data-action="u-award-history" data-name="${X(p.name)}">${X(p.name)}</button></td>${RESULT_METRICS.map(([metric])=>`<td class="center numeric">${p[metric]?.[0]||0} / ${p[metric]?.[1]||0}</td>`).join('')}<td class="center numeric"><strong>${p.total}</strong></td></tr>`),'hall-table award-count-table exact-table');

function sealResult(month){
  if(!ensureEdit())return false;const season=historySeason(month);if(!season)return false;
  checkpoint();const winners=winnersFrom(season.logs),old=(data.history||[]).find(h=>h.month===month);
  season.result={...season.result,sealed:true,confirmedAt:Date.now(),winners,fingerprint:resultFingerprint(season.logs)};
  const result={...old,month,clanRank:season.result.rank,memberCount:seasonSummary(month).count,winners:Object.fromEntries(RESULT_METRICS.map(([metric])=>[metric,winners[metric].map(p=>p.name)]))};
  data.awards??=[];
  for(const [metric]of RESULT_METRICS)for(let place=0;place<2;place++){
    const before=old?.winners?.[metric]?.[place],after=result.winners[metric][place];if(before===after)continue;
    if(before){const row=data.awards.find(p=>p.name===before);if(row){row[metric][place]=Math.max(0,row[metric][place]-1);row.total=Math.max(0,row.total-1);}}
    if(after){let row=data.awards.find(p=>p.name===after);if(!row){row={name:after,game:[0,0],contribution:[0,0],damage:[0,0],total:0};data.awards.push(row);}row[metric][place]++;row.total++;}
  }
  data.history??=[];if(old)Object.assign(old,result);else data.history.push(result);
  persist();closeDrawer();render();toast('월별 결과 확정',true);return true;
}

function lineupInput(kind){
  const value=kind==='converter'?ext.converterLineupText||'':'';
  return `<section class="lineup-text-entry" data-lineup-kind="${kind}"><label for="${kind}-lineup-text">캐릭터명 한 번에 입력</label><input id="${kind}-lineup-text" class="lineup-name-input" data-input="u-lineup-text" data-kind="${kind}" value="${X(value)}" placeholder="수사렌 수리코 수미미 수페코 사루카" autocomplete="off" spellcheck="false"><div class="lineup-text-feedback" role="status"></div><div class="lineup-order-feedback" role="status"></div><div class="lineup-preview"></div></section>`;
}
function lineupNames(kind){return Array.from({length:5},(_,i)=>document.getElementById((kind==='converter'?'convert-name-':'party-')+i)?.value||'');}
function setLineupNames(kind,names,stars=null){
  for(let i=0;i<5;i++){
    const select=document.getElementById((kind==='converter'?'convert-name-':'party-')+i);if(select)select.value=names[i]||'';
    if(kind==='tactic'){
      const star=select?.form?.querySelector(`[name="star-${i}"]`);if(star)star.value=String(stars?.[i]||defaultCharacterStars([names[i]])[0]);
    }
  }
  if(kind==='converter'){ext.converterNames=[...names];for(let i=0;i<5;i++){const alias=document.getElementById('convert-alias-'+i);if(alias&&!alias.value)alias.value=characterReference(names[i])?.aliases?.find(value=>/[ぁ-ヿ一-龯]/.test(value))||'';}refreshConverter();}
  updateLineupPreview(kind);
}
function updateLineupPreview(kind){
  const section=document.querySelector(`[data-lineup-kind="${kind}"]`);if(!section)return;
  const names=lineupNames(kind),actual=names.filter(Boolean),order=partyTools.lineupOrder(actual,data.characters);
  const warning=section.querySelector('.lineup-order-feedback');
  warning.innerHTML=order.inversions.length?`<span class="lineup-order-warning">위치 확인: ${X(order.inversions[0][0])} · ${X(order.inversions[0][1])}</span><button type="button" class="button quiet" data-action="u-sort-lineup" data-kind="${kind}">위치순 정렬</button>`:order.unknown.length?`<span class="field-help">위치 정보 미확인: ${X(order.unknown.join(', '))}</span>`:actual.length?'<span class="lineup-order-ok">위치순 확인</span>':'';
  section.querySelector('.lineup-preview').innerHTML=actual.length?party({party:actual,stars:kind==='converter'?defaultCharacterStars(actual):names.map((name,i)=>Number(document.querySelector(`[name="star-${i}"]`)?.value)||5).filter((n,i)=>names[i]),support:-1}):'';
  for(let i=0;i<5;i++){
    const select=document.getElementById((kind==='converter'?'convert-name-':'party-')+i);if(!select)continue;
    let face=select.parentElement.querySelector('.lineup-slot-face');if(!face){face=document.createElement('span');face.className='lineup-slot-face';select.before(face);}face.innerHTML=names[i]?portraitHtml(names[i]):'';
  }
}
function applyLineupText(input,composing=false){
  const kind=input.dataset.kind,section=input.closest('.lineup-text-entry'),parsed=partyTools.parseLineup(input.value,data.characters);
  if(kind==='converter')ext.converterLineupText=input.value;
  // The last Korean syllable stays in composition until the next key. Apply a
  // complete match immediately, without interrupting or rewriting the IME input.
  if(composing&&!parsed.valid)return;
  const messages=[];if(parsed.unknown.length)messages.push('찾지 못함: '+parsed.unknown.join(', '));if(parsed.ambiguous.length)messages.push('이름 확인: '+parsed.ambiguous.map(p=>p.token).join(', '));if(parsed.duplicates.length)messages.push('중복: '+parsed.duplicates.join(', '));
  if(parsed.names.length>5)messages.push('캐릭터는 5명까지 입력하세요.');
  section.querySelector('.lineup-text-feedback').textContent=messages.join(' · ')||(!input.value.trim()?'':parsed.valid?'편성에 적용됨':`${parsed.names.length}/5명`);
  section.querySelector('.lineup-text-feedback').classList.toggle('danger',!!messages.length);
  if(parsed.valid){const current=lineupNames(kind);if(parsed.names.some((name,index)=>current[index]!==name))setLineupNames(kind,parsed.names);}
}
const tacticFormWithoutNames=editCompleteTactic;
editCompleteTactic=id=>{
  tacticFormWithoutNames(id);const form=drawer.querySelector('form[data-form="v2-tactic"]');if(!form)return;
  form.querySelector('.tactic-lineup-form')?.insertAdjacentHTML('beforebegin',lineupInput('tactic'));
  if(!id)for(let i=0;i<5;i++){const select=form.querySelector(`[name="party-${i}"]`);select?.insertAdjacentHTML('afterbegin','<option value="">선택</option>');if(select)select.value='';}
  updateLineupPreview('tactic');
};
const converterWithoutNames=completeConverter;
completeConverter=()=>lineupInput('converter')+converterWithoutNames();
const tacticSaveWithoutValidation=saveCompleteTactic;
saveCompleteTactic=form=>{
  const fd=new FormData(form),names=Array.from({length:5},(_,i)=>String(fd.get('party-'+i)||''));
  if(names.some(name=>!data.characters.some(c=>c.name===name))||new Set(names).size!==5){toast('서로 다른 캐릭터 5명을 선택하세요.');return false;}
  return tacticSaveWithoutValidation(form);
};

const operationalRenderComplete=afterOperationalRender;
afterOperationalRender=()=>{operationalRenderComplete();if(ui.section==='tactics'&&ui.tabs.tactics==='converter')updateLineupPreview('converter');};
for(const action of ['u-confirm-result','u-seal-result','u-history-rank','u-insert-log','u-move-log'])writerActions.add(action);
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const action=button.dataset.action;if(!action.startsWith('u-')||action==='u-move-log')return;
  event.preventDefault();event.stopImmediatePropagation();
  if(action==='u-close-calculator'){button.closest('details').open=false;return;}
  if(action==='u-apply-estimate'||action==='u-apply-remaining'){
    const result=action==='u-apply-estimate'?estimateResult():{seconds:Math.min(90,timeToSec(document.getElementById('carry-remaining').value)+20)};
    if(result.error||!(result.seconds>0&&result.seconds<=90)){toast(result.error||'시간을 확인하세요.');return;}
    ext.externalSeconds=result.seconds;const field=document.getElementById('external-carry');if(field){field.value=fmtTime(result.seconds);updateExternal();}button.closest('details').open=false;return;
  }
  if(action==='u-sort-lineup'){
    const kind=button.dataset.kind,names=lineupNames(kind),order=partyTools.lineupOrder(names.filter(Boolean),data.characters);
    if(order.unknown.length){toast('위치를 확인할 수 없는 캐릭터가 있습니다.');return;}
    const stars=kind==='tactic'?names.map((name,i)=>Number(document.querySelector(`[name="star-${i}"]`)?.value)||5):null;
    setLineupNames(kind,order.sorted,stars?order.sorted.map(name=>stars[names.indexOf(name)]):null);return;
  }
  if(action==='u-confirm-result'){
    if(!ensureEdit())return;const month=button.dataset.id,season=historySeason(month);if(!season)return;
    openDrawer(month.replace('-','.')+' 결과 확정',rowTable(['항목','1위·2위'],RESULT_METRICS.map(([metric,label])=>`<tr><th>${label}</th><td class="winner-cell">${winnerText(winnersFrom(season.logs),metric)}</td></tr>`),'result-preview'),simpleButton('취소','close-drawer')+simpleButton('확정','u-seal-result',month,'primary'));return;
  }
  if(action==='u-seal-result'){sealResult(button.dataset.id);return;}
  if(action==='u-history-rank'){
    if(!ensureEdit())return;const month=button.dataset.id,result=historyResult(month);
    openDrawer(month.replace('-','.')+' 클랜 순위',`<input name="month" type="hidden" value="${month}"><div class="field"><label for="history-clan-rank">클랜 순위</label><input id="history-clan-rank" name="rank" type="number" min="1" required value="${result.rank||''}"></div>`,'<button class="button primary" type="submit">저장</button>','',false,'u-history-rank');return;
  }
  if(action==='u-award-history'){
    const name=button.dataset.name,rows=[];
    for(const month of historyMonths()){const result=historyResult(month);if(!result.sealed)continue;for(const [metric,label]of RESULT_METRICS)for(const [i,p]of(result.winners[metric]||[]).entries())if(p.name===name)rows.push(`<tr><td>${month.replace('-','.')}</td><td>${label}</td><td>${i+1}위</td></tr>`);}
    openDrawer(name+' 수상 기록',rowTable(['월','항목','순위'],rows),simpleButton('닫기','close-drawer'));return;
  }
  if(action==='u-insert-log')openInsertedLog(button.dataset.id,button.dataset.side);
},true);
document.addEventListener('submit',event=>{
  const form=event.target;if(form.dataset.form!=='u-history-rank')return;event.preventDefault();event.stopImmediatePropagation();if(!ensureEdit())return;
  const fd=new FormData(form),month=String(fd.get('month')),rank=Number(fd.get('rank'));if(!Number.isSafeInteger(rank)||rank<1){toast('순위를 확인하세요.');return;}
  checkpoint();const season=historySeason(month);if(season)season.result.rank=rank;
  data.history??=[];let row=data.history.find(h=>h.month===month);if(!row){row={month,winners:{game:[],contribution:[],damage:[]}};data.history.push(row);}row.clanRank=rank;persist();closeDrawer();render();toast('클랜 순위 저장',true);
},true);
document.addEventListener('input',event=>{if(event.target.dataset.input==='u-lineup-text')applyLineupText(event.target,event.isComposing);});
document.addEventListener('compositionend',event=>{if(event.target.dataset.input==='u-lineup-text')applyLineupText(event.target);});
document.addEventListener('change',event=>{if(event.target.id?.startsWith('party-')||event.target.name?.startsWith('star-'))updateLineupPreview('tactic');if(event.target.id?.startsWith('convert-name-'))updateLineupPreview('converter');});
document.addEventListener('toggle',event=>{if(event.target.matches?.('.calculator-popover')&&event.target.open)updateEstimator();},true);
document.addEventListener('click',event=>{for(const popover of document.querySelectorAll?.('.calculator-popover[open]')||[])if(!popover.contains(event.target))popover.open=false;});
document.addEventListener('keydown',event=>{if(event.key==='Escape')for(const popover of document.querySelectorAll?.('.calculator-popover[open]')||[])popover.open=false;});



function logPositionContext(id=null,anchorId=null,side='before'){
  const ordered=[...data.logs].sort((a,b)=>a.seq-b.seq);
  let index=ordered.length;
  if(id)index=ordered.findIndex(row=>row.id===id);
  else if(anchorId){index=ordered.findIndex(row=>row.id===anchorId);if(side==='after')index++;}
  if(index<0)throw Error('기준 기록을 찾지 못했습니다.');
  const month=structuredClone(engineMonth());month.events=structuredClone(ordered.slice(0,index));
  engineReplay(month);
  return {bosses:engineProgress(month),logs:month.events,index};
}
function entryLogContext(fd){
  const id=String(fd.get('logId')||''),anchor=String(fd.get('insertAnchor')||'');
  if(id||anchor)return logPositionContext(id,anchor,String(fd.get('insertSide')||'before'));
  return {bosses:data.bosses,logs:data.logs};
}
attackEntryState=fd=>{
  const old=data.logs.find(row=>row.id===String(fd.get('logId')||'')),context=entryLogContext(fd),boss=context.bosses.find(b=>b.id===Number(fd.get('boss')))||context.bosses[0];
  const stage=boss.stage,automatic=[2,3].includes(stage)&&fd.has('autoDamage');
  return {boss,old,stage,automatic,damage:automatic?Number(data.bossSettings.find(b=>b.id===boss.id).hp[stage]):numberValue(fd.get('damage'))*Number(fd.get('unit')||100000000)};
};
const originalEntryItems=entryItems;
entryItems=(kind,picker)=>{
  const inline=picker?.closest?.('tr[data-inline-log]');
  if(kind==='member'){if(inline)return data.members.filter(m=>memberSeasonActive(m,Number(inline.dataset.day))||m.id===picker.dataset.selected).map(m=>({value:m.id,label:m.name,member:m}));return originalEntryItems(kind,picker);}
  const form=picker?.closest?.('form[data-form="v2-log"]');
  let bosses=data.bosses;
  if(form)bosses=entryLogContext(new FormData(form)).bosses;
  else if(inline){const draft=ext.inlineLogDraft;bosses=inline.dataset.inlineLog==='draft'&&draft?logPositionContext(null,draft.anchor,draft.insertSide).bosses:logPositionContext(inline.dataset.inlineLog).bosses;}
  return bosses.map(b=>({value:String(b.id),label:b.id+' · '+b.name,disabled:b.locked&&picker?.dataset.allowLocked!=='1'}));
};
const originalLogEntry=openCompleteLog;
openCompleteLog=(id=null,bossId=null)=>{
  const insertion=ext.logInsertion,anchor=insertion?data.logs.find(row=>row.id===insertion.id):null;
  const context=id||anchor?logPositionContext(id,anchor?.id,insertion?.side):null;
  const previousBosses=data.bosses,previousDay=ui.day;
  if(context)data.bosses=context.bosses;
  if(anchor)ui.day=anchor.day;
  const selectedBoss=!id&&context?.bosses.find(b=>b.id===Number(bossId))?.locked?context.bosses.find(b=>!b.locked)?.id:bossId;
  try{originalLogEntry(id,selectedBoss);}finally{data.bosses=previousBosses;ui.day=previousDay;}
  const form=drawer.querySelector('form[data-form="v2-log"]');if(!form)return;
  if(anchor){
    form.insertAdjacentHTML('afterbegin',`<input type="hidden" name="insertAnchor" value="${X(anchor.id)}"><input type="hidden" name="insertSide" value="${insertion.side}"><p class="insert-log-note">${anchor.seq}번 기록 ${insertion.side==='before'?'앞':'뒤'}에 추가</p>`);
    const day=form.querySelector('[name=day]');if(day){day.value=String(anchor.day);if(day.tagName==='SELECT'){day.disabled=true;form.insertAdjacentHTML('afterbegin',`<input type="hidden" name="day" value="${anchor.day}">`);}}
  }
  completeLogPreview();
};
function chronologicalLogSide(side){return ext.logOrder==='asc'?side:side==='before'?'after':'before';}
function openInsertedLog(id,side){
  if(!ensureEdit())return;const anchor=data.logs.find(row=>row.id===id);if(!anchor)return;
  if(data.dayClosures.some(boundary=>boundary.day===anchor.day)){toast('마감을 취소한 뒤 추가하세요.');return;}
  const insertSide=chronologicalLogSide(side),context=logPositionContext(null,id,insertSide),boss=context.bosses.find(b=>b.id===anchor.boss&&!b.locked)||context.bosses.find(b=>!b.locked);
  ext.inlineLogDraft={anchor:id,side,insertSide,month:ui.month,day:anchor.day,memberId:anchor.memberId,boss:boss?.id||anchor.boss,damage:'',bonus:'0',carry:false};
  render();document.querySelector('[data-inline-log="draft"] [data-entry-search="member"]')?.focus();
}
completeLogPreview=()=>{
  const form=drawer.querySelector('form[data-form="v2-log"]');if(!form)return;
  syncAttackEntry(form);if(!form.querySelector('[name=boss]')?.value){document.getElementById('log-preview').textContent='';return;}
  const fd=new FormData(form),state=attackEntryState(fd),before=state.boss.hp,damage=state.damage||0,actual=Math.min(damage,before);
  document.getElementById('log-boss-preview').innerHTML=`<span>${state.stage}단계 ${state.boss.lap}회차</span><strong class="numeric">HP ${nf(before)}</strong>`;
  const estimate=damage>before?engineEstimate({hp:before,second:damage,seconds:90}):null;
  document.getElementById('log-preview').innerHTML=`<dl class="preview-values"><div><dt>실제 피해량</dt><dd>${nf(actual)}</dd></div><div><dt>공격 후 HP</dt><dd>${nf(Math.max(0,before-damage))}</dd></div>${estimate?.seconds?`<div><dt>예상 이월</dt><dd>${estimate.seconds}초</dd></div>`:''}</dl>`;
};
saveCompleteLog=form=>{
  if(!ensureEdit())return false;
  const fd=typeof form?.get==='function'&&typeof form?.has==='function'?form:new FormData(form),id=String(fd.get('logId')||''),old=data.logs.find(row=>row.id===id),entry=attackEntryState(fd);
  const memberId=String(fd.get('memberId')||''),boss=Number(fd.get('boss')),day=Number(fd.get('day')),carry=fd.has('usesCarry'),bonus=numberValue(fd.get('bonus')||0),damage=entry.damage;
  if(!Number.isSafeInteger(damage)||damage<=0){toast('피해량은 1 단위의 양의 정수로 입력하세요.');return false;}
  if(!Number.isSafeInteger(bonus)){toast('가산점은 양수 또는 음수의 정수로 입력하세요.');return false;}
  if(!data.members.some(member=>member.id===memberId)||!data.bossSettings.some(b=>b.id===boss)){toast('클랜원과 보스를 선택하세요.');return false;}
  if(!Number.isInteger(day)||day<1||day>data.rules.days||!memberSeasonActive(currentMember(memberId),day)){toast('참가 일차를 확인하세요.');return false;}
  if(data.dayClosures.some(boundary=>boundary.day===day)){toast('마감을 취소한 뒤 수정하세요.');return false;}
  if(!old&&entry.boss.locked){toast(entry.boss.lockedReason);return false;}
  const daily=data.logs.filter(row=>row.day===day&&row.memberId===memberId&&row.id!==id);
  if(!old&&!carry&&daily.filter(row=>!row.carry).length>=data.rules.daily){toast('기본 타수를 모두 사용했습니다.');return false;}
  const prefix=entryLogContext(fd).logs.filter(row=>row.day===day&&row.memberId===memberId&&row.id!==id);
  if(!old&&carry&&!prefix.some(row=>row.kill&&!row.carry&&!prefix.some(other=>other.carryFrom===row.id))){toast('사용할 이월이 없습니다.');return false;}
  const remaining=String(fd.get('remaining')||''),seconds=remaining?timeToSec(remaining):NaN;
  if(remaining&&!(seconds>=0&&seconds<=90)){toast('남은 시간을 확인하세요.');return false;}
  const value={memberId,boss,day,damage,damageMode:entry.automatic?'max':'manual',carry,usesCarry:carry,note:String(fd.get('note')||''),bonus:bonus/10000,gameAt:String(fd.get('gameAt')||''),carrySeconds:Number.isFinite(seconds)?Math.min(90,seconds+20):old?.carrySeconds||0};
  const record={...(old||{}),id:old?.id||uid(),...value};
  let next;
  try{next=old?data.logs.map(row=>row.id===id?record:row):logOrder.insertRecord(data.logs,record,String(fd.get('insertAnchor')||'')||null,String(fd.get('insertSide')||'after'));}catch(error){toast(error.message);return false;}
  checkpoint();if(old){Object.assign(old,value);next=data.logs;}data.logs=next;data.dayClosures=logOrder.refreshClosures(data.dayClosures,next);recalculateSeason();
  const saved=data.logs.find(row=>row.id===record.id);
  if(!old){ext.entryMember=memberId;ext.entryBoss=boss;ext.entryCarry=saved.kill&&!saved.carry&&!data.logs.some(row=>row.carryFrom===saved.id);ext.entryFeedback=currentMember(memberId).name+' · '+boss+'넴 '+nf(saved.damage)+' 등록';}
  persist();if(drawer.open)closeDrawer();ext.logInsertion=null;if(!old)ext.inlineLogDraft=null;render();
  if(!old)document.getElementById('quick-member')?.focus();
  toast(old?'기록 수정':'기록 등록',true);return true;
};
function moveLogRecord(id,anchorId,side){
  if(!ensureEdit())return false;
  const source=data.logs.find(row=>row.id===id);if(!source)return false;
  if(data.dayClosures.some(boundary=>boundary.day===source.day)){toast('마감을 취소한 뒤 이동하세요.');return false;}
  let next;try{next=logOrder.moveRecord(data.logs,id,anchorId,side);}catch(error){toast(error.message);return false;}
  checkpoint();data.logs=next;data.dayClosures=logOrder.refreshClosures(data.dayClosures,next);recalculateSeason();persist();render();toast('기록 순서 변경',true);return true;
}
function inlineLogFields(values){return {get:key=>values[key]??null,has:key=>Object.hasOwn(values,key)};}
function updateInlineLog(id,field,value){
  if(!ensureEdit())return false;
  if(!['memberId','boss','damage','bonus','carry'].includes(field))return false;
  const current=data.logs.find(row=>row.id===id);if(!current){toast('공격 기록을 찾지 못했습니다.');return false;}
  const canonical=field==='carry'?(value===true||value==='carry'):['damage','bonus','boss'].includes(field)?numberValue(value):String(value);
  const prior=field==='bonus'?Math.round((current.bonus||0)*10000):field==='carry'?!!current.carry:current[field];
  if(canonical===prior)return true;
  const values={logId:id,memberId:current.memberId,boss:current.boss,damage:current.damage,bonus:Math.round((current.bonus||0)*10000),day:current.day,unit:1,note:current.note||'',gameAt:current.gameAt||''};
  if(current.carry)values.usesCarry='on';
  if(current.damageMode==='max'&&field!=='damage')values.autoDamage='on';
  if(field==='carry'){if(canonical)values.usesCarry='on';else delete values.usesCarry;}
  else values[field]=value;
  return saveCompleteLog(inlineLogFields(values));
}
function commitInlineLogDraft(){
  const draft=ext.inlineLogDraft;if(!draft||draft.month!==ui.month)return false;
  return saveCompleteLog(inlineLogFields({memberId:draft.memberId,boss:draft.boss,damage:draft.damage,bonus:draft.bonus,day:draft.day,unit:1,note:'',gameAt:'',insertAnchor:draft.anchor,insertSide:draft.insertSide,...(draft.carry?{usesCarry:'on'}:{})}));
}
function inlineLogId(e,field,mobile){return `inline-log-${mobile?'m':'w'}-${e.inlineDraft?'draft':e.id}-${field}`;}
function inlineLogPicker(e,field,mobile){
  const kind=field==='memberId'?'member':'boss';
  return `<div class="inline-log-${kind}">${entrySearch(kind,inlineLogId(e,field,mobile),field,e[field],true).replace('type="search"',`type="search" data-inline-log-field="${field}" aria-label="${e.inlineDraft?'새':e.seq+'번'} 기록 ${kind==='member'?'클랜원':'보스'}"`)}</div>`;
}
function inlineLogNumber(e,field,mobile){
  const value=field==='bonus'?(e.inlineDraft?e.bonus:Math.round((e.bonus||0)*10000)):e.damage;
  return `<input class="inline-log-number ${field==='bonus'?'inline-log-bonus':''}" id="${inlineLogId(e,field,mobile)}" data-inline-log-field="${field}" type="text" inputmode="${field==='bonus'?'decimal':'numeric'}" value="${X(typeof value==='number'?nf(value):value)}" aria-label="${e.inlineDraft?'새':e.seq+'번'} 기록 ${field==='bonus'?'가산점':'피해량'}" ${field==='bonus'?'tabindex="-1" ':''}autocomplete="off">`;
}
function inlineLogType(e,mobile){
  const label=e.role==='초월'?'초월':e.kill?(e.carry?'관통':'격파'):e.carry?'이월타':'일반';
  return `<div class="inline-log-type"><span class="type-tag ${e.kill?'kill':e.carry?'carry':''}">${label}</span><label class="inline-log-carry"><input type="checkbox" id="${inlineLogId(e,'carry',mobile)}" data-inline-log-field="carry" aria-label="${e.inlineDraft?'새':e.seq+'번'} 기록 이월타 여부" ${e.carry?'checked':''}>이월</label></div>`;
}
function visibleLogMoveTarget(id,direction){
  const rows=getFilteredCompleteLogs(),index=rows.findIndex(row=>row.id===id),source=rows[index],target=rows[index+(direction==='up'?-1:1)];
  return source&&target&&source.day===target.day?target:null;
}
function moveVisibleLog(id,direction){
  const source=data.logs.find(row=>row.id===id),target=visibleLogMoveTarget(id,direction);
  if(!source||!target)return false;
  return moveLogRecord(id,target.id,target.seq<source.seq?'before':'after');
}
function logManagement(e){
  if(e.inlineDraft)return `<div class="log-manage-actions">${simpleButton('등록','inline-log-add','','primary')}${simpleButton('취소','inline-log-cancel')}</div>`;
  const closed=data.dayClosures.some(boundary=>boundary.day===e.day),disabled=closed?'disabled':'';
  return `<div class="log-manage-actions"><button type="button" class="log-drag-handle" draggable="${!closed}" data-drag-log="${e.id}" title="이 손잡이를 끌어 순서 이동" aria-label="${e.seq}번 기록 끌어서 이동" ${disabled}>⠿</button><button type="button" class="button quiet" data-action="u-move-log" data-id="${e.id}" data-direction="up" aria-label="${e.seq}번 기록 위로 이동" ${closed||!visibleLogMoveTarget(e.id,'up')?'disabled':''}>↑</button><button type="button" class="button quiet" data-action="u-move-log" data-id="${e.id}" data-direction="down" aria-label="${e.seq}번 기록 아래로 이동" ${closed||!visibleLogMoveTarget(e.id,'down')?'disabled':''}>↓</button>${simpleButton('삭제','entry-delete-log',e.id,'danger quiet')}<button type="button" class="button quiet" data-action="u-insert-log" data-id="${e.id}" data-side="before" aria-label="${e.seq}번 기록 앞에 추가" ${disabled}>+위</button><button type="button" class="button quiet" data-action="u-insert-log" data-id="${e.id}" data-side="after" aria-label="${e.seq}번 기록 뒤에 추가" ${disabled}>+아래</button></div>`;
}
function logDetailCells(e,editing,mobile=false){
  const cls=mobile?'mobile-log-extra':'extra-cell',bonus=nf(Math.round((e.bonus||0)*10000));
  return `<td class="right numeric ${cls} actual-damage">${e.inlineDraft?'—':nf(e.actual)}</td><td class="right numeric ${cls}">${editing?inlineLogNumber(e,'bonus',mobile):bonus}</td>${[points(e.contribution),nf(Math.round(e.game)),nf(e.before),nf(e.after)].map(value=>`<td class="right numeric ${cls}">${e.inlineDraft?'—':value}</td>`).join('')}`;
}
function completeLogRow(e,{editing,details,mini,mobile}){
  const writable=editing&&!data.dayClosures.some(boundary=>boundary.day===e.day),context=e.inlineDraft?logPositionContext(null,e.anchor,e.insertSide).bosses.find(b=>b.id===Number(e.boss)):null;
  const label=e.role==='초월'?'초월':e.kill?(e.carry?'관통':'격파'):e.carry?'이월타':'일반';
  return `<tr ${e.inlineDraft?'class="log-inline-draft"':`data-log-id="${e.id}"`} data-day="${e.day}"${editing?` data-inline-log="${e.inlineDraft?'draft':e.id}"`:''}>${mini?'':`<td class="progress-cell">${e.inlineDraft?'<span>새 기록</span>':ext.sequence?`<small class="mobile-seq" title="기록 순번">#${e.seq}</small>`:''}<span>${e.day}일차</span><small>${context?.stage??e.stage}단계 ${context?.lap??e.lap}회차</small></td>`}<td>${writable?inlineLogPicker(e,'boss',mobile):`<span class="boss-tag" style="${bossStyle(e.boss)}">${e.boss}넴</span>`}</td><td class="${mobile?'mobile-log-member':''}">${writable?inlineLogPicker(e,'memberId',mobile):memberLink(currentMember(e.memberId))}</td><td class="right numeric ${mobile?'mobile-log-damage':''}">${writable?inlineLogNumber(e,'damage',mobile):`<strong>${nf(e.damage)}</strong>`}${mini?`<small>${e.day}일차 · ${e.stage}단계 ${e.lap}회차</small>`:''}</td><td>${writable?inlineLogType(e,mobile):`<span class="type-tag ${e.kill?'kill':e.carry?'carry':''}">${label}</span>`}</td>${details?logDetailCells(e,writable,mobile):''}${editing?`<td class="log-manage ${mobile?'mobile-log-actions':''}">${logManagement(e)}</td>`:''}</tr>`;
}
completeLogTable=(logs,mini=false)=>{
  const editing=!mini&&adminMode(),details=!mini&&ext.details;
  const headers=[...(!mini?['일차·회차']:[]),'보스','클랜원','기록 피해량','유형',...(details?['실제 피해량','가산점','기여도','인게임','이전 HP','남은 HP']:[]),...(editing?['관리']:[])];
  const rows=[...logs],draft=ext.inlineLogDraft;
  if(editing&&draft?.month===ui.month){const at=rows.findIndex(e=>e.id===draft.anchor);if(at>=0)rows.splice(at+(draft.side==='after'?1:0),0,{...draft,inlineDraft:true});}
  const wide=rowTable(headers,rows.map(e=>completeLogRow(e,{editing,details,mini,mobile:false})),`battle-table ${details?'expanded':''} ${mini?'small-log':''} ${editing?'inline-editable':''}`);
  const mobile=!mini?`<div class="battle-mobile-only">${rowTable(headers,rows.map(e=>completeLogRow(e,{editing,details,mini,mobile:true})),`battle-mobile-table ${details?'mobile-detail':''} ${editing?'can-edit inline-editable':''}`)}</div>`:'';
  return `<div class="battle-wide-table">${wide}</div>`+mobile;
};
for(const action of ['inline-log-add'])writerActions.add(action);
const chooseEntryBeforeInline=chooseEntry;
chooseEntry=(input,value)=>{
  const row=input.closest('tr[data-inline-log]'),id=row?.dataset.inlineLog,field=input.dataset.inlineLogField;
  if(!chooseEntryBeforeInline(input,value))return false;
  if(!id||!field)return true;
  if(id==='draft'){if(ext.inlineLogDraft)ext.inlineLogDraft[field]=value;}
  else if(!updateInlineLog(id,field,value))return false;
  const next=inlineLogId({id,inlineDraft:id==='draft'},field==='memberId'?'boss':'damage',input.id.startsWith('inline-log-m-'));
  setTimeout(()=>document.getElementById(next)?.focus(),0);return true;
};
const showEntryResultsBeforeInline=showEntryResults;
showEntryResults=(input,all=false)=>{
  showEntryResultsBeforeInline(input,all);if(!input.dataset.inlineLogField)return;
  const box=input.closest('.search-picker').querySelector('[role=listbox]'),rect=input.getBoundingClientRect();
  Object.assign(box.style,{position:'fixed',left:Math.max(8,Math.min(rect.left,window.innerWidth-248))+'px',top:Math.max(8,Math.min(rect.bottom+4,window.innerHeight-248))+'px',width:'240px',right:'auto',maxHeight:'240px'});
};
document.addEventListener('input',event=>{
  const input=event.target,row=input.closest?.('tr[data-inline-log]'),field=input.dataset.inlineLogField;
  if(row?.dataset.inlineLog==='draft'&&field&&!input.dataset.entrySearch&&ext.inlineLogDraft)ext.inlineLogDraft[field]=field==='carry'?input.checked:input.value;
});
document.addEventListener('change',event=>{
  const input=event.target,row=input.closest?.('tr[data-inline-log]'),field=input.dataset.inlineLogField;if(!row||!field)return;
  if(input.dataset.entrySearch)return;
  if(row.dataset.inlineLog==='draft'){
    if(ext.inlineLogDraft)ext.inlineLogDraft[field]=field==='carry'?input.checked:input.value;
    if(field==='carry'){const tag=row.querySelector('.inline-log-type .type-tag');if(tag){tag.textContent=input.checked?'이월타':'일반';tag.classList.toggle('carry',input.checked);}}return;
  }
  if(field==='carry'){
    const id=input.id;if(!updateInlineLog(row.dataset.inlineLog,field,input.checked)){input.checked=!!data.logs.find(e=>e.id===row.dataset.inlineLog)?.carry;input.setAttribute('aria-invalid','true');}
    else setTimeout(()=>document.getElementById(id)?.focus(),0);
  }
});
document.addEventListener('focusout',event=>{
  const input=event.target,row=input.closest?.('tr[data-inline-log]'),field=input.dataset.inlineLogField;
  if(!row||!field||!input.isConnected)return;
  const nextId=event.relatedTarget?.id;
  if(input.dataset.entrySearch){
    if(input.closest('.search-picker').contains(event.relatedTarget))return;
    if(!resolveEntry(input)){input.setCustomValidity('검색 결과에서 선택하세요.');input.reportValidity();return;}
  }else if(row.dataset.inlineLog!=='draft'&&field!=='carry'){
    if(!updateInlineLog(row.dataset.inlineLog,field,input.value)){input.setAttribute('aria-invalid','true');return;}
  }
  if(nextId?.startsWith('inline-log-'))setTimeout(()=>document.getElementById(nextId)?.focus(),0);
});
document.addEventListener('keydown',event=>{
  const input=event.target;if(!input.dataset.inlineLogField||input.dataset.entrySearch||event.isComposing||event.keyCode===229)return;
  if(event.key==='Enter'){
    event.preventDefault();const row=input.closest('tr[data-inline-log]'),id=row.dataset.inlineLog,field=input.dataset.inlineLogField;
    if(id==='draft'){
      for(const picker of row.querySelectorAll('[data-entry-search]'))if(!resolveEntry(picker)){picker.reportValidity();picker.focus();return;}
      if(ext.inlineLogDraft)ext.inlineLogDraft[field]=field==='carry'?input.checked:input.value;
      commitInlineLogDraft();
    }else if(field!=='carry'&&updateInlineLog(id,field,input.value)){
      document.getElementById(inlineLogId({id},field==='damage'?'memberId':field,input.id.startsWith('inline-log-m-')))?.focus();
    }
  }
  if(event.key==='Escape'){const row=input.closest('tr[data-inline-log]');if(row?.dataset.inlineLog==='draft'){ext.inlineLogDraft=null;render();}else render();}
});
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action="inline-log-add"],[data-action="inline-log-cancel"]');if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  if(button.dataset.action==='inline-log-add'){
    for(const input of button.closest('tr').querySelectorAll('[data-entry-search]'))if(!resolveEntry(input)){input.setCustomValidity('검색 결과에서 선택하세요.');input.reportValidity();input.focus();return;}
    commitInlineLogDraft();
  }else{ext.inlineLogDraft=null;render();}
},true);
const closeBeforeInsertionCleanup=closeDrawer;
closeDrawer=()=>{ext.logInsertion=null;closeBeforeInsertionCleanup();};
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action="u-move-log"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
  moveVisibleLog(button.dataset.id,button.dataset.direction);
},true);
function clearLogDropMarks(){for(const row of document.querySelectorAll?.('.log-drop-before,.log-drop-after,.log-dragging')||[])row.classList.remove('log-drop-before','log-drop-after','log-dragging');}
document.addEventListener('dragstart',event=>{
  const handle=event.target.closest('[data-drag-log]');if(!handle||!adminMode())return;
  ext.draggedLog=handle.dataset.dragLog;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',ext.draggedLog);handle.closest('tr')?.classList.add('log-dragging');
});
document.addEventListener('dragover',event=>{
  const row=event.target.closest('tr[data-log-id]');if(!row||!ext.draggedLog||!adminMode())return;
  event.preventDefault();event.dataTransfer.dropEffect='move';const rect=row.getBoundingClientRect(),side=event.clientY<rect.top+rect.height/2?'before':'after';
  for(const other of document.querySelectorAll('.log-drop-before,.log-drop-after'))other.classList.remove('log-drop-before','log-drop-after');row.classList.add('log-drop-'+side);ext.logDrop={id:row.dataset.logId,side};
});
document.addEventListener('drop',event=>{
  const row=event.target.closest('tr[data-log-id]');if(!row||!ext.draggedLog)return;
  event.preventDefault();const id=ext.draggedLog,side=chronologicalLogSide(ext.logDrop?.id===row.dataset.logId?ext.logDrop.side:'before');ext.draggedLog=null;ext.logDrop=null;clearLogDropMarks();if(id!==row.dataset.logId)moveLogRecord(id,row.dataset.logId,side);
});
document.addEventListener('dragend',()=>{ext.draggedLog=null;ext.logDrop=null;clearLogDropMarks();});



// Retain the useful original workflows inside the new navigation.
const simplePastedRows=pasteRows;
pasteRows=(text,t)=>/^(?:[01oOxX⭕❌]\t){5}[01oOxX⭕❌]\t/m.test(text)?simplePastedRows(text,t):legacyTools.pastedRows(text,[],t.party,data.characters);
tacticRows=t=>{if(!t.rows)t.rows=pasteRows(t.text,t);return t.rows;};
subpageNames.overview.logs='배틀로그';
fullOverview=()=>{
  if(ext.importMode&&adminMode())return batchImportPage();
  const tab=ui.tabs.overview,name=tab==='members'?'대시보드':tab==='logs'?'배틀로그':'클랜전';
  const action=tab==='logs'?simpleButton('이미지 등록','v2-import-images'):'';
  const heading=titleBar(name,action)+pageTabs([['bosses','상황판'],['members','대시보드'],['logs','배틀로그']]);
  if(tab==='members')return heading+operatingLine(false)+fullDashboard();
  if(tab==='logs')return heading+battleLogContent();
  return heading+operatingLine(true)+bossStrip()+`<details class="fold optional-stats"><summary>전투 통계</summary>${overviewCharts()}</details>`;
};
fullBattle=()=>{ui.section='overview';ui.tabs.overview='logs';return fullOverview();};

findPlans=()=>{
  const rows=data.tactics.filter(t=>!t.hidden&&!t.deletedAt&&t.stage===4&&t.category!=='carry').map(t=>({...t,characters:t.party,expectedDamage:t.damage,manualCount:t.hands}));
  const catalog=data.characters.map(c=>({...c,name:String(c.unitId||c.name),aliases:[c.name,...(c.aliases||[])]}));
  const result=legacyTools.planThreeAttacks(rows,catalog,{distinctBosses:true,limit:12});
  ext.foundPlans=result.plans.map(plan=>({ids:plan.attacks.map(a=>a.combo.id),damage:plan.totalDamage,supports:Object.fromEntries(plan.attacks.map(a=>[a.combo.id,a.supportIndex])),borrowCount:plan.borrowCount}));
};
function applyFoundPlan(index){const plan=ext.foundPlans?.[index];if(!plan)return;ui.picks=[...plan.ids];ext.selectedSupports={...plan.supports};ext.onlyPicks=true;render();}
const rawSelectedParties=selectedParties;
selectedParties=()=>rawSelectedParties().map(t=>({...t,support:ext.selectedSupports?.[t.id]??t.support}));
const rawVisibleTactics=visibleTactics;
visibleTactics=()=>rawVisibleTactics().map(t=>ui.picks.includes(t.id)&&ext.selectedSupports?.[t.id]!==undefined?{...t,support:ext.selectedSupports[t.id]}:t);
recommendationDistribution=()=>{
  if(!ext.distributionOpen)return '';
  const plans=ext.foundPlans||[];
  return `<section class="distribution-panel" aria-label="추천 분배">${plans.length?rowTable(['추천 조합 · 대여','합계 기대딜',''],plans.slice(0,5).map((p,i)=>`<tr><td>${p.ids.map(id=>{const t=tacticById(id),support=p.supports?.[id]??-1;return `<span class="distribution-team"><span class="distribution-boss" style="${bossStyle(t.boss)}">${t.boss}넴</span><small>${support>=0?X(t.party[support]):'대여 자유'}</small></span>`;}).join('')}</td><td class="right numeric"><strong>${expectedDamageValue(p.damage)}</strong></td><td class="right">${simpleButton('선택','v2-use-plan',String(i),'quiet')}</td></tr>`),'distribution-table'):'<p class="no-rows">겹치지 않는 3타 조합이 없습니다.</p>'}</section>`;
};

const logContentWithoutWarnings=battleLogContent;
battleLogContent=()=>{
  const warnings=data.replayWarnings||[];
  return (warnings.length?`<div class="log-warning-summary"><button class="button" data-action="r-log-warnings" aria-pressed="${!!ext.warningOnly}">확인할 기록 ${new Set(warnings.map(w=>w.id)).size}건${ext.warningOnly?' · 전체 보기':''}</button><span>이월 연결·기본 타수를 확인하세요.</span></div>`:'')+logContentWithoutWarnings();
};
const logsWithoutWarningFilter=getFilteredCompleteLogs;
getFilteredCompleteLogs=()=>{const rows=logsWithoutWarningFilter();if(!ext.warningOnly)return rows;const ids=new Set((data.replayWarnings||[]).map(w=>w.id));return rows.filter(row=>ids.has(row.id));};
const logTableWithoutWarnings=completeLogTable;
completeLogTable=(logs,mini=false)=>{
  const warnings=new Map();for(const warning of data.replayWarnings||[])warnings.set(warning.id,[...(warnings.get(warning.id)||[]),warning.message]);
  return logTableWithoutWarnings(logs,mini).replace(/<tr data-log-id="([^"]+)"[\s\S]*?<\/tr>/g,(row,id)=>{
    const messages=warnings.get(id);if(!messages)return row;
    return row.replace('<tr ','<tr class="log-warning-row" ').replace('</td>',`<span class="log-warning-badge" title="${X(messages.join(' · '))}">확인</span></td>`);
  });
};
const tableExportWithoutLogTab=exportCurrentTable;
exportCurrentTable=()=>{
  if(ui.section==='overview'&&ui.tabs.overview==='logs'){
    downloadCsv([['일차','회차','보스','클랜원','기록 피해량','유형','실제 피해량','가산점','기여도','인게임'],...getFilteredCompleteLogs().map(e=>[e.day,e.lap,e.boss,currentMember(e.memberId).name,e.damage,e.role||logTypeLabel(e.type),e.actual,Math.round((e.bonus||0)*10000),e.contribution,e.game])],`배틀로그_${ui.month}_${ext.allDays?'전체':ui.day+'일차'}.csv`);return;
  }
  tableExportWithoutLogTab();
};

function loadExternalDraft(){
  if(ext.externalDraftLoaded)return;ext.externalDraftLoaded=true;
  try{const saved=JSON.parse(localStorage.getItem('nyang-external-tactic-carry:v1')||'null');if(saved){ext.externalText=saved.source||'';ext.externalBase=timeToSec(saved.original)||90;ext.externalSeconds=timeToSec(saved.carry)||90;}}catch{}
}
const externalWithoutDraft=completeExternal;
completeExternal=()=>{loadExternalDraft();return externalWithoutDraft();};
updateExternal=()=>{
  const source=document.getElementById('external-text'),output=document.getElementById('external-output');if(!source||!output)return;
  const original=document.getElementById('external-base').value,carry=document.getElementById('external-carry').value;
  ext.externalText=source.value;ext.externalBase=timeToSec(original);ext.externalSeconds=timeToSec(carry);
  try{localStorage.setItem('nyang-external-tactic-carry:v1',JSON.stringify({source:source.value,original,carry}));}catch{}
  try{const result=legacyTools.shiftExternalTacticTimes(source.value,ext.externalBase,ext.externalSeconds);output.textContent=result.text;output.removeAttribute('aria-invalid');}
  catch(error){output.textContent=error.message;output.setAttribute('aria-invalid','true');}
};

// Match the OCR parser's nickname key so equivalent names cannot belong to two people.
const imageNicknameKey=value=>String(value??'').normalize('NFKC').replace(/[\s_()[\]·.\-]/g,'').toLowerCase();
let imageImportController;
function imageImportMonth(){
  if(!ext.imageImportMonth||ext.imageImportMonthKey!==ui.month||ext.imageImportMonth.events!==data.logs){
    ext.imageImportMonthKey=ui.month;
    ext.imageImportMonth={...engineMonth(),memberIds:Object.keys(data.memberships),dayBreaks:data.dayClosures.map(c=>({afterSeq:c.afterSeq??Math.max(0,...data.logs.filter(e=>e.day<=c.day).map(e=>e.seq)),nextDay:c.day+1}))};
  }
  return ext.imageImportMonth;
}
function screenshotImporter(){
  if(imageImportController)return imageImportController;
  imageImportController=legacyTools.createBattleImageImport({
    getApp:()=>({active:ui.month,roster:data.members}),getMonth:imageImportMonth,
    canEdit:adminMode,unlock:()=>toggleWriter(),notify:message=>toast(message),render:()=>render(),
    saveNicknameAlias:(memberId,alias)=>{
      if(!adminMode()||!ensureEdit())return {ok:false,error:'관리자 작성 권한과 편집 가능한 동기화 상태가 필요합니다.'};
      const raw=String(alias??''),value=raw.normalize('NFKC').replace(/\s+/g,' ').trim(),key=imageNicknameKey(value);
      if(!key||value.length>40||/[\x00-\x1f\x7f]/.test(raw))return {ok:false,error:'닉네임 형식을 확인하세요.'};
      const member=data.members.find(p=>p.id===memberId);
      if(!member)return {ok:false,error:'클랜원을 찾지 못했습니다.'};
      const conflict=data.members.find(p=>p.id!==memberId&&[p.name,...(p.aliases||[])].some(name=>imageNicknameKey(name)===key));
      if(conflict)return {ok:false,error:'이미 다른 클랜원('+conflict.name+')에게 연결된 이름입니다.'};
      if([member.name,...(member.aliases||[])].some(name=>imageNicknameKey(name)===key))return {ok:true};
      checkpoint();member.aliases=[...(member.aliases||[]),value];persist();
      return {ok:true};
    },
    removeNicknameAlias:(memberId,alias)=>{
      if(!adminMode()||!ensureEdit())return {ok:false,error:'관리자 작성 권한과 편집 가능한 동기화 상태가 필요합니다.'};
      const member=data.members.find(p=>p.id===memberId);
      if(!member)return {ok:false,error:'클랜원을 찾지 못했습니다.'};
      const key=imageNicknameKey(alias),aliases=(member.aliases||[]).filter(name=>imageNicknameKey(name)!==key);
      if(aliases.length===(member.aliases||[]).length)return {ok:true};
      checkpoint();member.aliases=aliases;persist();
      return {ok:true};
    },
    navigate:()=>{ext.importMode=false;nav('overview','logs');},beforeCommit:()=>checkpoint(),
    replay:month=>engineReplay(month),
    persist:()=>{
      const month=imageImportMonth();data.logs=month.events.map(e=>({...e,usesCarry:!!e.carry,note:e.note??e.memo??''}));
      data.dayClosures=month.dayBreaks.map(boundary=>({...boundary,day:boundary.nextDay-1,count:data.logs.filter(e=>e.seq<=boundary.afterSeq).length,at:data.dayClosures.find(c=>c.day===boundary.nextDay-1)?.at||new Date().toISOString()}));
      recalculateSeason();persist();ext.imageImportMonth=null;
    }
  });
  return imageImportController;
}
